// Bluetooth lab B8 Host.  uv run pio run -d labs/ble-lab-b8 -e ble-lab-b8 -t upload
// Roles swap: until now a phone or laptop was the central and the board the peripheral. Here the
// board is the central, like a laptop. It connects to devices, explores what they offer (read-only:
// the public basics, never anything vendor-specific), and hosts your own BLE keyboard and mouse:
// it pairs (you type the passkey on the keyboard), reads the Report Map, subscribes to the input
// reports, and turns them into text and a paint cursor on the screen.
//
// Wiring: the screen from lesson 03. The push button on GPIO 5 is optional (it does what BOOT does).
//
// Views: devices · explore · keyboard · mouse · reports · link · log
// Button: click = next view, double-click = the view's action, long press = the next step
// (connect -> host -> disconnect). While a numeric comparison waits: click = yes, long press = no.
// Serial: help lists the commands. Shared code: kit/lib/ble-kit (hid_report.h decodes the Report Map).
#include "b8_views.h"
#include "ble_lab.h"
#include "central.h"

namespace {

b8::Central central;
b8v::Pick pick;
ble::Heard rows[ble::ScanTable::kMax];
int rowCount = 0;
int scroll = 0;
b8::Progress prog;
b8::Input in;
b8::Tree tr;

const ble::Heard *picked() {
  for (int i = 0; i < rowCount; i++)
    if (pick.matches(rows[i])) return &rows[i];
  return nullptr;
}

// ---- Views ------------------------------------------------------------------------------------

bool connectedNow() { return central.connected(); }

void drawDevices(BleLab &, FrameBuffer &fb, float t) { b8v::devices(fb, rows, rowCount, pick, central, prog, t); }
void drawExplore(BleLab &, FrameBuffer &fb, float t) {
  b8::tree().copyTo(tr);
  b8v::explore(fb, tr, scroll, prog, t);
}
void drawKeyboard(BleLab &, FrameBuffer &fb, float t) {
  b8::input().copyTo(in);
  b8v::keyboard(fb, in, prog, connectedNow(), central.hid.layout(), t);
}
void drawMouse(BleLab &, FrameBuffer &fb, float t) {
  b8::input().copyTo(in);
  b8v::mouse(fb, in, prog, connectedNow(), t);
}
void drawReports(BleLab &, FrameBuffer &fb, float t) {
  b8::input().copyTo(in);
  b8v::reports(fb, in, central.hid, prog, connectedNow(), t);
}
void drawLink(BleLab &lab, FrameBuffer &fb, float t) { bv::link(fb, lab.state(), t, "this board"); }
void drawLog(BleLab &, FrameBuffer &fb, float) { bv::log(fb); }

const BleView kViews[] = {
    {"devices", drawDevices, "next"},
    {"explore", drawExplore, "more"},
    {"keyboard", drawKeyboard, "clear"},
    {"mouse", drawMouse, "clear"},
    {"reports", drawReports, nullptr},
    {"link", drawLink, nullptr},
    {"log", drawLog, nullptr},
};

// ---- Commands ---------------------------------------------------------------------------------

void cmdScan(BleLab &lab, const String &, const String &lower) {
  if (!lower.isEmpty() && lower != "on" && lower != "off") return lab.warn("scan | scan on | scan off");
  const bool on = lower.isEmpty() ? !NimBLEDevice::getScan()->isScanning() : lower == "on";
  if (on && central.connected()) return lab.warn("connected: disconnect first (one link at a time in this lab)");
  if (on) central.startScan(), BLE_NOTE(Info, "scanning");
  else central.stopScan(), BLE_NOTE(Info, "scan paused");
}

void cmdList(BleLab &, const String &, const String &) {
  Serial.printf("%d connectable devices (strongest first):\n", rowCount);
  for (int i = 0; i < rowCount; i++) {
    const ble::Heard &h = rows[i];
    char addr[18];
    h.addrText(addr, sizeof(addr));
    Serial.printf("%3d  %4d dBm  %-14s  %s  %s%s%s\n", i + 1, int(h.rssiAvg), ad::kindName(h.kind), addr, h.label(),
                  h.kind == ad::Kind::Input ? "  [HID]" : "", central.isBonded(h.addr, h.addrType) ? "  [bonded]" : "");
  }
}

void pickIndex(int i) {
  if (i < 0 || i >= rowCount) return;
  pick.take(rows[i]);
  BLE_NOTE(Info, "picked %d: %s", i + 1, rows[i].label());
}

void cmdNext(BleLab &, const String &, const String &) {
  if (!rowCount) return;
  int at = -1;
  for (int i = 0; i < rowCount; i++)
    if (pick.matches(rows[i])) at = i;
  pickIndex((at + 1) % rowCount);
}

void cmdConnect(BleLab &lab, const String &arg, const String &) {
  long n = 0;
  if (!arg.isEmpty()) {
    if (!BleLab::number(arg, 1, std::max(rowCount, 1), n)) return lab.warn("connect <1-%d> (the number from list)", rowCount);
    pickIndex(n - 1);
  }
  const ble::Heard *h = picked();
  if (!h) return lab.warn("nothing picked: devices view double-click, or connect <n>");
  if (central.connected()) return lab.warn("already connected: disconnect first");
  b8::Request r;
  r.job = b8::Job::Connect;
  memcpy(r.addr, h->addr, 6);
  r.addrType = h->addrType;
  strlcpy(r.name, h->label(), sizeof(r.name));
  scroll = 0;
  central.submit(r);
}

void simple(b8::Job job) {
  b8::Request r;
  r.job = job;
  central.submit(r);
}

void cmdDisconnect(BleLab &lab, const String &, const String &) {
  if (!central.connected()) return lab.warn("nothing connected");
  simple(b8::Job::Disconnect);
}
void cmdExplore(BleLab &lab, const String &, const String &) {
  if (!central.connected()) return lab.warn("connect first");
  scroll = 0;
  simple(b8::Job::Explore);
}
void cmdPair(BleLab &lab, const String &, const String &) {
  if (!central.connected()) return lab.warn("connect first");
  simple(b8::Job::Pair);
}
void cmdHost(BleLab &lab, const String &, const String &) {
  if (!central.connected()) return lab.warn("connect a keyboard or mouse first");
  simple(b8::Job::Host);
}
void cmdForget(BleLab &, const String &, const String &) { simple(b8::Job::Forget); }

void cmdBoot(BleLab &lab, const String &, const String &lower) {
  if (lower != "on" && lower != "off") return lab.warn("boot on | boot off   (now %s)", central.boot() ? "on" : "off");
  central.setBoot(lower == "on");
  BLE_NOTE(Info, "%s protocol from the next host", central.boot() ? "boot" : "report");
  if (prog.phase == b8::Phase::Hosting) simple(b8::Job::Boot);
}

void cmdLayout(BleLab &lab, const String &, const String &lower) {
  if (lower != "us" && lower != "de") return lab.warn("layout us | layout de   (the layout your keyboard is printed with)");
  central.hid.setLayout(lower == "de" ? hid::Layout::De : hid::Layout::Us);
  BLE_NOTE(Info, "layout %s: the same keys, other letters", lower == "de" ? "German (QWERTZ)" : "US (QWERTY)");
}

void cmdClear(BleLab &lab, const String &, const String &) {
  b8::input().edit([](b8::Input &i) {
    i.len = 0;
    i.strokeHead = 0;
  });
  (void)lab;
}

void cmdMore(BleLab &, const String &, const String &) {
  b8::tree().copyTo(tr);
  scroll = scroll + 8 >= tr.count ? 0 : scroll + 8;
}

void cmdYes(BleLab &lab, const String &, const String &) {
  if (!central.links.answer(central.client(), true)) lab.warn("no numeric comparison is waiting");
}
void cmdNo(BleLab &lab, const String &, const String &) {
  if (!central.links.answer(central.client(), false)) lab.warn("no numeric comparison is waiting");
}
void cmdPasskey(BleLab &lab, const String &arg, const String &) {
  long pin = 0;
  if (!BleLab::number(arg, 0, 999999, pin)) return lab.warn("passkey <6 digits shown on the device>");
  if (!central.links.enter(central.client(), uint32_t(pin))) lab.warn("no passkey entry is waiting");
}

const BleCommand kCommands[] = {
    {"scan", "[on|off]", "listen for connectable devices (alone: toggle)", cmdScan},
    {"list", "", "print the connectable devices", cmdList},
    {"next", "", "pick the next device", cmdNext},
    {"connect", "[n]", "connect to device n (or the picked one), then explore", cmdConnect},
    {"explore", "", "discover its services again and read the basics", cmdExplore},
    {"more", "", "scroll the explore view", cmdMore},
    {"pair", "", "encrypt + bond (keyboards: type the passkey on them)", cmdPair},
    {"host", "", "use it: read the Report Map, subscribe to its reports", cmdHost},
    {"boot", "on|off", "boot protocol (fixed formats) instead of the Report Map", cmdBoot},
    {"layout", "us|de", "how key codes become letters", cmdLayout},
    {"clear", "", "empty the editor and the drawing", cmdClear},
    {"disconnect", "", "hang up", cmdDisconnect},
    {"forget", "", "delete every bond on the board", cmdForget},
    {"yes", "", "numeric comparison: the numbers match", cmdYes},
    {"no", "", "numeric comparison: they don't", cmdNo},
    {"passkey", "<digits>", "the device shows a passkey: type it here", cmdPasskey},
};

// ---- Hooks ------------------------------------------------------------------------------------

void setup(BleLab &) { central.begin(); }

void tick(BleLab &lab) {
  // Only connectable devices: a broadcast-only beacon can't be connected to.
  const int n = central.table.snapshot(rows, ble::ScanTable::kMax, 20000);
  rowCount = 0;
  for (int i = 0; i < n; i++)
    if (rows[i].connectable) rows[rowCount++] = rows[i];
  if (!pick.set && rowCount) pick.take(rows[0]);
  b8::progress().copyTo(prog);
  const int want = central.wantView;
  if (want >= 0) {
    central.wantView = -1;
    lab.setView(want);
  }
}

// The long press walks the path: connect -> host -> disconnect.
bool gesture(BleLab &lab, Gesture g, bool) {
  if (central.links.comparing() && g != Gesture::DoubleClick) {
    central.links.answer(central.client(), g == Gesture::Click);
    return true;
  }
  if (g != Gesture::LongPress) return false;
  b8::tree().copyTo(tr);
  const char *next = !central.connected() ? "connect" : (tr.hasHid && prog.phase != b8::Phase::Hosting) ? "host" : "disconnect";
  Serial.printf("> %s   (long press)\n", next);
  lab.runLine(next);
  return true;
}

const BleLabSpec kSpec{
    "ble-lab-b8", "B8", "Host", "Bench B8", kViews, sizeof(kViews) / sizeof(kViews[0]), 0,
    kCommands, sizeof(kCommands) / sizeof(kCommands[0]), setup, tick, gesture, nullptr,
};

BleLab lab(kSpec);

}  // namespace

void setup() { lab.begin(); }

void loop() { lab.loop(); }

// B8's screens (320 x 170):
//   devices   connectable devices around you; keyboards and mice marked HID, bonded ones with a key
//   explore   the connected device's GATT tree: services, characteristics (props + read values), descriptors
//   keyboard  a little text editor: what you type on YOUR keyboard appears here, modifiers light up
//   mouse     a paint toy: left button draws, right changes colour, middle clears, wheel = brush size
//   reports   the raw input reports, each byte coloured by the Report Map field it belongs to
//   (link and log come from kit/lib/ble-kit)
#pragma once

#include "ble_views.h"
#include "central.h"
#include "host_state.h"

namespace b8v {

using namespace bv;

struct Pick {
  uint8_t addr[6] = {};
  uint8_t type = 0;
  bool set = false;
  bool matches(const ble::Heard &h) const { return set && h.addrType == type && memcmp(h.addr, addr, 6) == 0; }
  void take(const ble::Heard &h) {
    memcpy(addr, h.addr, 6);
    type = h.addrType;
    set = true;
  }
};

inline void hidGlyph(FrameBuffer &fb, int x, int y, uint16_t c) {
  fb.drawRect(x, y, 13, 8, c);
  for (int i = 0; i < 3; i++) fb.drawFastHLine(x + 2 + i * 3, y + 2, 2, c), fb.drawFastHLine(x + 3 + i * 3, y + 4, 2, c);
  fb.drawFastHLine(x + 4, y + 6, 5, c);
}

// A busy phase as a panel over the view: what the central task is waiting for right now.
inline void busy(FrameBuffer &fb, const b8::Progress &p, float t) {
  if (p.phase == b8::Phase::Idle || p.phase == b8::Phase::Hosting) return;
  fb.fillRoundRect(40, 74, 240, 46, 8, kPanel);
  fb.drawRoundRect(40, 74, 240, 46, 8, pal::amber);
  char v[48];
  snprintf(v, sizeof(v), "%s %s", b8::phaseName(p.phase), p.phase == b8::Phase::Connecting ? p.target : "");
  bold(fb, 52, 94, pal::ink, v);
  // Packets going back and forth while we wait.
  for (int i = 0; i < 3; i++) {
    const float k = fmodf(t * 0.9f + i / 3.0f, 1.0f);
    fb.fillCircle(56 + int(k * 208), 108, 2, i == 0 ? kBlue : mix(kBlue, kPanel, 120));
  }
  snprintf(v, sizeof(v), "%lus", static_cast<unsigned long>((millis() - p.since) / 1000));
  small(fb, 250, 82, pal::muted, v);
}

inline void devices(FrameBuffer &fb, const ble::Heard *rows, int n, const Pick &pick, b8::Central &c, const b8::Progress &p, float t) {
  small(fb, 6, 34, pal::dim, "#  device (connectable only)       signal  dBm");
  for (int i = 0; i < n && i < 9; i++) {
    const ble::Heard &h = rows[i];
    const int y = 46 + i * 12;
    const bool sel = pick.matches(h);
    if (sel) fb.fillRect(0, y - 2, kW, 12, kPanel);
    char v[24];
    snprintf(v, sizeof(v), "%d", i + 1);
    small(fb, 6, y, pal::muted, v);
    if (h.kind == ad::Kind::Input) hidGlyph(fb, 20, y - 1, pal::teal);
    char label[22];
    strlcpy(label, h.label(), sizeof(label));
    small(fb, 38, y, sel ? pal::ink : pal::muted, label);
    if (c.isBonded(h.addr, h.addrType)) keyIcon(fb, 168, y - 3, pal::amber);
    signalBars(fb, 230, y - 4, int(h.rssiAvg), rssiColour(int(h.rssiAvg)));
    snprintf(v, sizeof(v), "%d", int(h.rssiAvg));
    small(fb, 256, y, rssiColour(int(h.rssiAvg)), v);
    if (h.kind == ad::Kind::Input) small(fb, 284, y, pal::teal, "HID");
  }
  if (n == 0) {
    small(fb, 6, 60, pal::muted, "Nothing connectable yet. Put your keyboard or");
    small(fb, 6, 72, pal::muted, "mouse in pairing mode (hold its Bluetooth key).");
  }
  busy(fb, p, t);
}

inline void explore(FrameBuffer &fb, const b8::Tree &tr, int scroll, const b8::Progress &p, float t) {
  if (tr.count == 0) {
    small(fb, 6, 44, pal::muted, "Connect to a device first: devices view,");
    small(fb, 6, 56, pal::muted, "pick it (double-click), then long press.");
    small(fb, 6, 76, pal::muted, "Explore lists what it offers. We only READ the");
    small(fb, 6, 88, pal::muted, "public basics (name, maker, model, battery).");
    return busy(fb, p, t);
  }
  char v[56];
  snprintf(v, sizeof(v), "%.18s  %d services %d chars", tr.device[0] ? tr.device : "device", tr.services, tr.characteristics);
  small(fb, 6, 34, pal::ink, v);
  const int rows = (tr.vendorOnly || tr.hasHid) ? 8 : 10;
  for (int r = 0; r < rows && scroll + r < tr.count; r++) {
    const b8::Node &nd = tr.nodes[scroll + r];
    const int y = 46 + r * 11, x = 6 + nd.level * 10;
    const uint16_t c = nd.level == 0 ? kBlue : nd.level == 1 ? pal::ink : pal::dim;
    if (nd.uuid16) snprintf(v, sizeof(v), "%04X %s", nd.uuid16, nd.name);
    else snprintf(v, sizeof(v), "%s", nd.name);
    small(fb, x, y, c, v);
    if (nd.level == 1) {
      char props[8] = "";
      int k = 0;
      if (nd.props & 0x02) props[k++] = 'R';
      if (nd.props & 0x0C) props[k++] = 'W';
      if (nd.props & 0x10) props[k++] = 'N';
      if (nd.props & 0x20) props[k++] = 'I';
      props[k] = 0;
      small(fb, 160, y, pal::muted, props);
    }
    if (nd.value[0]) {
      char val[24];
      strlcpy(val, nd.value, sizeof(val));
      small(fb, 186, y, nd.level == 0 ? pal::dim : pal::teal, val);
    }
  }
  if (tr.count > rows) {
    snprintf(v, sizeof(v), "%d-%d of %d", scroll + 1, std::min(scroll + rows, tr.count), tr.count);
    small(fb, 252, 34, pal::muted, v);
  }
  if (tr.hasHid) small(fb, 6, 140, pal::teal, "A keyboard or mouse (HID 1812): long press = host");
  else if (tr.vendorOnly && tr.audio) {
    small(fb, 6, 134, pal::amber, "This is the JBL app's own service. The audio");
    small(fb, 6, 144, pal::amber, "goes over Classic Bluetooth: this chip has none.");
  } else if (tr.vendorOnly) {
    small(fb, 6, 140, pal::amber, "Only the maker's own services: its app speaks them.");
  }
  busy(fb, p, t);
}

inline void modCaps(FrameBuffer &fb, int y, uint8_t mods) {
  static const char *const caps[] = {"Ctl", "Sft", "Alt", "Cmd", "Ctl", "Sft", "AGr", "Cmd"};
  for (int i = 0; i < 8; i++) {
    const int x = 6 + i * 26 + (i >= 4 ? 8 : 0);
    const bool on = mods & (1 << i);
    fb.fillRoundRect(x, y, 23, 12, 2, on ? pal::amber : kPanel);
    small(fb, x + 3, y + 2, on ? pal::night : pal::muted, caps[i]);
  }
}

inline void hint(FrameBuffer &fb, const b8::Progress &p, bool connected, const char *what) {
  char v[56];
  if (!connected) snprintf(v, sizeof(v), "No %s yet: connect one on the devices view.", what);
  else if (p.phase != b8::Phase::Hosting) snprintf(v, sizeof(v), "Connected. Long press (or host) to use the %s.", what);
  else snprintf(v, sizeof(v), "This device sends no %s reports.", what);
  small(fb, 6, 60, pal::muted, v);
}

inline void keyboard(FrameBuffer &fb, const b8::Input &in, const b8::Progress &p, bool connected, hid::Layout layout, float t) {
  if (!p.keyboard) {
    hint(fb, p, connected, "keyboard");
    return busy(fb, p, t);
  }
  // The text in the screen's built-in 6x8 font at size 2 (12 x 16 px): 26 columns, 5 lines.
  // cp437 mode = its 256 glyphs include the German umlauts.
  constexpr int kCols = 26, kLines = 5;
  // Where each line starts; only the last kLines are kept (a ring), however much was typed.
  int starts[kLines], lines = 0, col = 0;
  starts[lines++ % kLines] = 0;
  for (int i = 0; i < in.len; i++) {
    if (in.text[i] == '\n' || col == kCols) {
      starts[lines++ % kLines] = in.text[i] == '\n' ? i + 1 : i;
      col = in.text[i] == '\n' ? 0 : 1;
    } else {
      col++;
    }
  }
  const int shown = std::min(lines, kLines);
  fb.setFont(nullptr);
  fb.cp437(true);
  fb.setTextSize(2);
  fb.setTextColor(pal::ink);
  int cx = 6, cy = 36;
  for (int l = 0; l < shown; l++) {
    const int line = lines - shown + l;
    const int from = starts[line % kLines], to = l + 1 < shown ? starts[(line + 1) % kLines] : in.len;
    cy = 36 + l * 17;
    fb.setCursor(6, cy);
    for (int i = from; i < to; i++)
      if (in.text[i] != '\n') fb.write(in.text[i]);
    cx = fb.getCursorX();
    if (to > from && in.text[to - 1] == '\n' && l + 1 == shown) cx = 6;
  }
  fb.setTextSize(1);
  fb.cp437(false);
  if (int(t * 2) & 1) fb.fillRect(cx, cy, 10, 15, pal::teal);  // the cursor
  modCaps(fb, 124, in.mods);
  char v[48];
  int at = snprintf(v, sizeof(v), "keys");
  for (int i = 0; i < in.heldN && at < 40; i++) at += snprintf(v + at, sizeof(v) - at, " %02X", in.held[i]);
  small(fb, 228, 126, in.heldN ? pal::teal : pal::dim, v);
  snprintf(v, sizeof(v), "layout %s  %lu keys  %s", layout == hid::Layout::De ? "DE" : "US", static_cast<unsigned long>(in.keystrokes),
           p.boot ? "boot protocol" : "report protocol");
  small(fb, 6, 144, pal::muted, v);
  if (in.mediaAt && millis() - in.mediaAt < 2500) {
    fb.fillRoundRect(196, 140, 118, 14, 3, kViolet);
    small(fb, 202, 143, pal::night, in.media);
  }
}

inline uint16_t paint(uint8_t i) {
  static const uint16_t c[] = {kBlue, pal::teal, pal::amber, pal::coral, kViolet, pal::ink};
  return c[i % 6];
}

inline void mouse(FrameBuffer &fb, const b8::Input &in, const b8::Progress &p, bool connected, float t) {
  if (!p.mouse) {
    hint(fb, p, connected, "mouse");
    return busy(fb, p, t);
  }
  // The drawing: consecutive points with the button down are joined.
  const uint32_t n = std::min<uint32_t>(in.strokeHead, b8::Input::kStrokes);
  for (uint32_t i = in.strokeHead - n; i < in.strokeHead; i++) {
    const b8::Stroke &s = in.strokes[i % b8::Input::kStrokes];
    if (!s.down) continue;
    fb.fillCircle(s.x, s.y, s.size / 2, paint(s.colour));
    if (i > in.strokeHead - n) {
      const b8::Stroke &prev = in.strokes[(i - 1) % b8::Input::kStrokes];
      if (prev.down)
        for (int w = -(s.size / 2); w <= s.size / 2; w++) fb.drawLine(prev.x, prev.y + w, s.x, s.y + w, paint(s.colour));
    }
  }
  // Trail: where the cursor was, fading.
  const uint32_t tn = std::min<uint32_t>(in.trailHead, b8::Input::kTrail);
  for (uint32_t i = in.trailHead - tn; i < in.trailHead; i++) {
    const uint8_t age = uint8_t((in.trailHead - i) * 255 / (b8::Input::kTrail + 1));
    fb.fillCircle(in.trailX[i % b8::Input::kTrail], in.trailY[i % b8::Input::kTrail], 1, mix(pal::muted, pal::night, age));
  }
  // A click: a ripple where it happened.
  const uint32_t since = millis() - in.clickAt;
  if (in.clickAt && since < 500) fb.drawCircle(in.clickX, in.clickY, 4 + since / 20, mix(pal::ink, pal::night, uint8_t(since / 2)));
  // The cursor: an arrow.
  const int x = in.mx, y = in.my;
  fb.fillTriangle(x, y, x, y + 12, x + 8, y + 9, pal::ink);
  fb.drawLine(x + 3, y + 9, x + 6, y + 15, pal::ink);
  // Palette and brush.
  for (int i = 0; i < 6; i++) {
    fb.fillRect(6 + i * 12, 146, 10, 8, paint(i));
    if (i == in.colour) fb.drawRect(5 + i * 12, 145, 12, 10, pal::ink);
  }
  fb.fillCircle(90, 150, in.brush / 2 + 1, paint(in.colour));
  char v[48];
  snprintf(v, sizeof(v), "L draw  R colour  M clear  wheel %u", in.brush);
  small(fb, 104, 147, pal::muted, v);
}

// The colour of byte b in a report: which Report Map field starts in it.
inline uint16_t byteColour(const b8::HidHost &h, const b8::RawReport &r, int b) {
  if (r.kind == b8::ReportKind::BootKeyboard) return b == 0 ? pal::amber : b == 1 ? pal::dim : pal::teal;
  if (r.kind == b8::ReportKind::BootMouse) return b == 0 ? pal::amber : b == 1 ? kBlue : b == 2 ? kViolet : pal::coral;
  for (int i = 0; i < h.map.count; i++) {
    const hid::Field &f = h.map.fields[i];
    if (f.reportId != r.id) continue;
    const int from = f.bitOffset, to = f.bitOffset + f.size * f.count;
    if (b * 8 + 7 < from || b * 8 >= to) continue;
    if (f.constant) return pal::dim;
    if (f.page == hid::kPageKeyboard) return f.variable ? pal::amber : pal::teal;
    if (f.page == hid::kPageButton) return pal::amber;
    if (f.page == hid::kPageDesktop) return f.usage == hid::kUsageX ? kBlue : f.usage == hid::kUsageY ? kViolet : pal::coral;
    if (f.page == hid::kPageConsumer) return pal::teal;
    return pal::muted;
  }
  return pal::muted;
}

inline void reports(FrameBuffer &fb, const b8::Input &in, const b8::HidHost &h, const b8::Progress &p, bool connected, float t) {
  if (p.phase != b8::Phase::Hosting) {
    hint(fb, p, connected, "keyboard or mouse");
    return busy(fb, p, t);
  }
  char v[48];
  snprintf(v, sizeof(v), "Report Map %d B, %d fields%s", p.mapBytes, p.fields, p.boot ? " (boot: fixed)" : "");
  small(fb, 6, 34, pal::muted, v);
  const uint32_t n = std::min<uint32_t>(in.reportHead, b8::Input::kReports);
  static const char *const kinds[] = {"kbd", "mouse", "media", "other", "bootK", "bootM"};
  for (uint32_t k = 0; k < n; k++) {
    const b8::RawReport &r = in.reports[(in.reportHead - n + k) % b8::Input::kReports];
    const int y = 46 + k * 19;
    snprintf(v, sizeof(v), "#%u %s", r.id, kinds[static_cast<int>(r.kind)]);
    small(fb, 6, y, pal::ink, v);
    for (int b = 0; b < r.len && b < 12; b++) {
      snprintf(v, sizeof(v), "%02X", r.data[b]);
      small(fb, 66 + b * 16, y, byteColour(h, r, b), v);
    }
    small(fb, 66, y + 9, pal::muted, r.decoded);
  }
  if (n == 0) small(fb, 6, 60, pal::muted, "Press a key or move the mouse.");
}

}  // namespace b8v

// B8 as the central: the board does what a phone or laptop does with a Bluetooth device.
//
//   scan      listen (B1's table), connectable devices only
//   connect   send CONNECT_IND to one of them; from now on WE set the connection timing
//   explore   discover its services, characteristics and descriptors, read the public basics
//   pair      ask for encryption (a keyboard shows us nothing: we show the passkey, you type it)
//   host      read the Report Map, subscribe to the input reports, and listen
//
// Connecting and discovering block for hundreds of milliseconds (pairing for as long as you take
// to type), so they run in their own task, the "central task", fed through a queue. loop() never
// waits: it keeps drawing, and the passkey overlay can appear while the central task is blocked.
#pragma once

#include <NimBLEDevice.h>
#include <esp_random.h>

#include "ble_link.h"
#include "hid_host.h"
#include "host_state.h"
#include "scan_table.h"
#include "server_link.h"

namespace b8 {

enum class Job : uint8_t { Connect, Explore, Pair, Host, Boot, Disconnect, Forget, Rescan };

struct Request {
  Job job = Job::Explore;
  uint8_t addr[6] = {};
  uint8_t addrType = 0;
  bool autoHost = false;  // Connect: go straight on to host (a bonded keyboard coming back)
  int32_t arg = 0;
  char name[24] = "";
};

// Standard characteristic names, for the explore view.
inline const char *chrName(uint16_t u) {
  switch (u) {
    case 0x2A00: return "Device Name";
    case 0x2A01: return "Appearance";
    case 0x2A04: return "Preferred Params";
    case 0x2A05: return "Service Changed";
    case 0x2A19: return "Battery Level";
    case 0x2A22: return "Boot Kbd Input";
    case 0x2A24: return "Model Number";
    case 0x2A25: return "Serial Number";
    case 0x2A26: return "Firmware Rev";
    case 0x2A27: return "Hardware Rev";
    case 0x2A28: return "Software Rev";
    case 0x2A29: return "Manufacturer";
    case 0x2A32: return "Boot Kbd Output";
    case 0x2A33: return "Boot Mouse Input";
    case 0x2A37: return "Heart Rate";
    case 0x2A4A: return "HID Information";
    case 0x2A4B: return "Report Map";
    case 0x2A4C: return "HID Control";
    case 0x2A4D: return "Report";
    case 0x2A4E: return "Protocol Mode";
    case 0x2A50: return "PnP ID";
    case 0x2AA6: return "Address Resolution";
    case 0x2AC9: return "RPA Only";
    case 0x2B29: return "Client Features";
    case 0x2B2A: return "Database Hash";
    case 0x2B3A: return "Server Features";
    case 0x2900: return "Extended Props";
    case 0x2901: return "User Description";
    case 0x2902: return "CCCD (subscribe)";
    case 0x2904: return "Format";
    case 0x2908: return "Report Reference";
    default: return nullptr;
  }
}

// The only values explore reads: public, standard, harmless. Never anything vendor-specific.
inline bool readable(uint16_t u) {
  switch (u) {
    case 0x2A00: case 0x2A01: case 0x2A19: case 0x2A24: case 0x2A26: case 0x2A27: case 0x2A28: case 0x2A29: case 0x2A50: return true;
    default: return false;
  }
}

inline uint16_t short16(const NimBLEUUID &u) {
  if (u.bitSize() != 16) return 0;
  return BLE_UUID16(u.getBase())->value;
}

// ---- The link from the central's side --------------------------------------------------------

class ClientLink : public NimBLEClientCallbacks {
 public:
  QueueHandle_t jobs = nullptr;  // to ask the central task for a rescan

  void onConnect(NimBLEClient *c) override {
    const NimBLEConnInfo info = c->getConnInfo();
    ble::link().edit([&](ble::LinkState &s) {
      s.peer = ble::Peer{};
      ble::fillPeer(s.peer, info);
      strlcpy(s.peer.name, name_, sizeof(s.peer.name));
      s.radio = ble::Radio::Connected;
      s.scanning = false;
      s.connections++;
      s.connectedAt = millis();
      s.rxOps = s.txOps = s.rxBytes = s.txBytes = 0;
    });
    BLE_NOTE(Good, "connected: we are the central");
    BLE_NOTE(Info, "interval %.2f ms (our choice), MTU next", info.getConnInterval() * 1.25f);
  }

  void onConnectFail(NimBLEClient *, int reason) override { BLE_NOTE(Bad, "connect failed (%d)", reason); }

  void onDisconnect(NimBLEClient *, int reason) override {
    ble::link().edit([&](ble::LinkState &s) {
      s.connections = 0;
      s.radio = ble::Radio::Off;
      s.lastDisconnect = reason;
      s.passkey = 0;
    });
    progress().edit([](Progress &p) { p = Progress{}; });
    pendingCompare_ = false;
    BLE_NOTE(Warn, "disconnected 0x%02X: %s", reason & 0xFF, ble::disconnectReason(reason));
    Request r;
    r.job = Job::Rescan;
    if (jobs) xQueueSend(jobs, &r, 0);
  }

  void onMTUChange(NimBLEClient *, uint16_t mtu) override {
    ble::link().edit([&](ble::LinkState &s) { s.peer.mtu = mtu; });
    BLE_NOTE(Info, "MTU %u agreed", mtu);
  }

  // Passkey entry where WE display: a keyboard has no screen, so you type these digits on it.
  uint32_t onPassKeyDisplay(NimBLEConnInfo &) override {
    const uint32_t key = esp_random() % 1000000;
    ble::link().edit([&](ble::LinkState &s) { s.passkey = key ? key : 1, s.passkeyCompare = false, s.passkeySince = millis(); });
    BLE_NOTE(Warn, "type %06lu on the keyboard, then Enter", static_cast<unsigned long>(key));
    return key;
  }

  // The other side has a screen and a keypad, and shows the digits: type them in the monitor.
  void onPassKeyEntry(NimBLEConnInfo &) override {
    awaitingEntry_ = true;
    BLE_NOTE(Warn, "the device shows a passkey: type passkey <6 digits>");
  }

  void onConfirmPasskey(NimBLEConnInfo &, uint32_t pin) override {
    pendingCompare_ = true;
    ble::link().edit([&](ble::LinkState &s) { s.passkey = pin ? pin : 1, s.passkeyCompare = true, s.passkeySince = millis(); });
    BLE_NOTE(Warn, "compare %06lu with the device (click = yes)", static_cast<unsigned long>(pin));
  }

  void onAuthenticationComplete(NimBLEConnInfo &info) override {
    awaitingEntry_ = false;
    pendingCompare_ = false;
    ble::link().edit([&](ble::LinkState &s) {
      ble::fillPeer(s.peer, info);
      s.passkey = 0;
    });
    if (info.isEncrypted())
      BLE_NOTE(Good, "secured: %s%s, key %u B", info.isAuthenticated() ? "passkey" : "Just Works", info.isBonded() ? ", bonded" : "", info.getSecKeySize());
    else
      BLE_NOTE(Bad, "pairing failed: still plain text");
  }

  void onIdentity(NimBLEConnInfo &info) override {
    ble::link().edit([&](ble::LinkState &s) { ble::fillPeer(s.peer, info); });
    BLE_NOTE(Info, "identity address %s", info.getIdAddress().toString().c_str());
  }

  void setName(const char *n) { strlcpy(name_, n, sizeof(name_)); }

  // From loop(): answers to a numeric comparison or a passkey entry.
  bool comparing() const { return pendingCompare_; }
  bool answer(NimBLEClient *c, bool yes) {
    if (!pendingCompare_ || !c) return false;
    pendingCompare_ = false;
    NimBLEDevice::injectConfirmPasskey(c->getConnInfo(), yes);
    ble::link().edit([](ble::LinkState &s) { s.passkey = 0; });
    BLE_NOTE(Info, "you said %s", yes ? "yes, it matches" : "no");
    return true;
  }
  bool enter(NimBLEClient *c, uint32_t pin) {
    if (!awaitingEntry_ || !c) return false;
    awaitingEntry_ = false;
    return NimBLEDevice::injectPassKey(c->getConnInfo(), pin);
  }

 private:
  char name_[24] = "";
  volatile bool pendingCompare_ = false, awaitingEntry_ = false;
};

// ---- The central task --------------------------------------------------------------------------

class Central : public NimBLEScanCallbacks {
 public:
  ble::ScanTable table;
  HidHost hid;
  ClientLink links;

  void begin() {
    // Keyboards ask for MITM protection; we can only display, so they get passkey entry. A mouse
    // (no keys, no screen) falls back to Just Works. Bond, and keep each other's identity keys.
    NimBLEDevice::setSecurityAuth(true, true, true);
    NimBLEDevice::setSecurityIOCap(BLE_HS_IO_DISPLAY_ONLY);
    NimBLEDevice::setSecurityInitKey(BLE_SM_PAIR_KEY_DIST_ENC | BLE_SM_PAIR_KEY_DIST_ID);
    NimBLEDevice::setSecurityRespKey(BLE_SM_PAIR_KEY_DIST_ENC | BLE_SM_PAIR_KEY_DIST_ID);
    queue_ = xQueueCreate(6, sizeof(Request));
    links.jobs = queue_;
    client_ = NimBLEDevice::createClient();
    client_->setClientCallbacks(&links, false);
    client_->setConnectTimeout(8000);
    refreshBonds();
    NimBLEScan *scan = NimBLEDevice::getScan();
    scan->setScanCallbacks(this, true);
    scan->setMaxResults(0);
    scan->setActiveScan(true);
    scan->setInterval(100);
    scan->setWindow(100);
    startScan();
    xTaskCreatePinnedToCore(task, "central", 8192, this, 1, nullptr, 1);
    if (bondCount_) BLE_NOTE(Info, "%d bonded device(s): reconnecting when one advertises", bondCount_);
  }

  bool submit(const Request &r) {
    if (xQueueSend(queue_, &r, 0) == pdTRUE) return true;
    BLE_NOTE(Warn, "busy: try again in a moment");
    return false;
  }

  NimBLEClient *client() { return client_; }
  bool connected() { return client_ && client_->isConnected(); }
  bool busy() const { return busy_; }

  void setBoot(bool on) { boot_ = on; }
  bool boot() const { return boot_; }

  bool isBonded(const uint8_t *a, uint8_t type) {
    bool hit = false;
    portENTER_CRITICAL(&lock_);
    for (int i = 0; i < bondCount_; i++) hit |= bondTypes_[i] == type && memcmp(bonds_[i], a, 6) == 0;
    portEXIT_CRITICAL(&lock_);
    return hit;
  }

  void startScan() {
    NimBLEScan *scan = NimBLEDevice::getScan();
    if (scan->isScanning()) return;
    if (scan->start(0, false, true)) ble::link().edit([](ble::LinkState &s) { s.radio = ble::Radio::Scanning, s.scanning = true; });
  }
  void stopScan() {
    NimBLEDevice::getScan()->stop();
    ble::link().edit([](ble::LinkState &s) {
      s.scanning = false;
      if (s.radio == ble::Radio::Scanning) s.radio = ble::Radio::Off;
    });
  }

  // NimBLE task: every packet heard. A bonded keyboard that shows up again gets reconnected.
  void onResult(const NimBLEAdvertisedDevice *d) override {
    table.record(d);
    if (!d->isConnectable() || busy_ || connected() || millis() - lastAuto_ < 10000) return;
    if (!isBonded(d->getAddress().getVal(), d->getAddress().getType())) return;
    lastAuto_ = millis();
    Request r;
    r.job = Job::Connect;
    memcpy(r.addr, d->getAddress().getVal(), 6);
    r.addrType = d->getAddress().getType();
    r.autoHost = true;
    strlcpy(r.name, d->haveName() ? d->getName().c_str() : "bonded device", sizeof(r.name));
    BLE_NOTE(Good, "bonded %s is back: reconnecting", r.name);
    xQueueSend(queue_, &r, 0);
  }

  // Asked for by loop() when the view should follow (hosting a keyboard -> keyboard view).
  volatile int wantView = -1;
  enum : int { kViewExplore = 1, kViewKeyboard = 2, kViewMouse = 3 };

 private:
  static void task(void *arg) {
    auto *self = static_cast<Central *>(arg);
    Request r;
    for (;;)
      if (xQueueReceive(self->queue_, &r, portMAX_DELAY) == pdTRUE) {
        self->busy_ = true;
        self->run(r);
        self->busy_ = false;
      }
  }

  void run(const Request &r) {
    switch (r.job) {
      case Job::Connect:
        if (connectTo(r) && explore() && r.autoHost) host();
        break;
      case Job::Explore: explore(); break;
      case Job::Pair: pair(); break;
      case Job::Host: host(); break;
      case Job::Boot:
        if (connected() && progress_().phase == Phase::Hosting) host();
        break;
      case Job::Disconnect:
        if (connected()) client_->disconnect();
        break;
      case Job::Forget:
        if (connected()) client_->disconnect(), vTaskDelay(pdMS_TO_TICKS(300));
        NimBLEDevice::deleteAllBonds();
        refreshBonds();
        BLE_NOTE(Info, "every bond deleted: pair again to use a keyboard");
        break;
      case Job::Rescan:
        hid.reset();
        startScan();
        break;
    }
  }

  Progress progress_() {
    Progress p;
    progress().copyTo(p);
    return p;
  }
  void phase(Phase ph) {
    progress().edit([&](Progress &p) { p.phase = ph, p.since = millis(); });
  }

  bool connectTo(const Request &r) {
    if (connected()) {
      BLE_NOTE(Warn, "already connected: disconnect first");
      return false;
    }
    stopScan();
    links.setName(r.name);
    progress().edit([&](Progress &p) {
      p = Progress{};
      p.phase = Phase::Connecting;
      p.since = millis();
      strlcpy(p.target, r.name, sizeof(p.target));
    });
    ble::link().edit([](ble::LinkState &s) { s.radio = ble::Radio::Connecting; });
    BLE_NOTE(Tx, "CONNECT_IND to %s", r.name);
    const NimBLEAddress addr(r.addr, r.addrType);
    if (!client_->connect(addr, true, false, true)) {
      BLE_NOTE(Bad, "no answer from %s (err %d): still advertising?", r.name, client_->getLastError());
      phase(Phase::Idle);
      startScan();
      return false;
    }
    return true;
  }

  bool explore() {
    if (!connected()) return BLE_NOTE(Warn, "connect first"), false;
    phase(Phase::Discovering);
    BLE_NOTE(Tx, "discovering services...");
    static Tree t;  // 4 KB: built here, then copied under the lock
    t = Tree{};
    strlcpy(t.device, progress_().target, sizeof(t.device));
    const uint32_t started = millis();
    const std::vector<NimBLERemoteService *> &services = client_->getServices(true);
    const bool encrypted = client_->getConnInfo().isEncrypted();
    bool standard = false, vendor = false;  // anything beyond the GAP/GATT basics?
    for (NimBLERemoteService *svc : services) {
      const uint16_t su = short16(svc->getUUID());
      t.services++;
      if (su == 0x1812) t.hasHid = true;
      const bool basic = su == 0x1800 || su == 0x1801, known = su && ad::service16Name(su);
      if (known && !basic && su != 0x180A && su != 0x180F) standard = true;  // info and battery don't count
      if (!known && !basic) vendor = true;
      add(t, 0, su, su ? (ad::service16Name(su) ? ad::service16Name(su) : "service") : "vendor service", "");
      if (!su) snprintf(t.nodes[t.count - 1].value, sizeof(t.nodes[0].value), "%.26s", svc->getUUID().toString().c_str());
      for (NimBLERemoteCharacteristic *chr : svc->getCharacteristics(true)) {
        const uint16_t cu = short16(chr->getUUID());
        t.characteristics++;
        char value[28] = "";
        // Read only the public basics. A HID device locks even those until it is paired, and a
        // locked read would start pairing by itself: leave that to `pair`/`host`.
        if (readable(cu) && chr->canRead()) {
          if (t.hasHid && !encrypted) strlcpy(value, "locked until paired", sizeof(value));
          else formatValue(cu, chr->readValue(), value, sizeof(value));
        }
        add(t, 1, cu, cu && chrName(cu) ? chrName(cu) : "vendor value", value);
        Node &n = t.nodes[t.count - 1];
        n.props = uint8_t((chr->canRead() ? 0x02 : 0) | (chr->canWriteNoResponse() ? 0x04 : 0) | (chr->canWrite() ? 0x08 : 0) |
                          (chr->canNotify() ? 0x10 : 0) | (chr->canIndicate() ? 0x20 : 0));
        if (cu == 0x2A00 && value[0]) strlcpy(t.device, value, sizeof(t.device));
        for (NimBLERemoteDescriptor *d : chr->getDescriptors(true)) {
          const uint16_t du = short16(d->getUUID());
          add(t, 2, du, du && chrName(du) ? chrName(du) : "descriptor", "");
        }
      }
    }
    t.vendorOnly = vendor && !standard;
    const ble::LinkState ls = ble::link().get();
    t.audio = strstr(t.device, "JBL") != nullptr || strstr(progress_().target, "JBL") != nullptr || strstr(ls.peer.name, "JBL") != nullptr;
    tree().edit([&](Tree &shared) {
      const uint32_t v = shared.version;
      shared = t;
      shared.version = v;
    });
    phase(Phase::Idle);
    BLE_NOTE(Good, "%d services, %d characteristics in %lu ms", t.services, t.characteristics, static_cast<unsigned long>(millis() - started));
    if (t.hasHid) BLE_NOTE(Info, "it is a keyboard/mouse (1812): type host");
    else if (t.vendorOnly && t.audio) BLE_NOTE(Info, "JBL app's own service only: audio uses Classic BT");
    else if (t.vendorOnly) BLE_NOTE(Info, "only the maker's own services: its app speaks them");
    wantView = kViewExplore;
    return true;
  }

  bool pair() {
    if (!connected()) return BLE_NOTE(Warn, "connect first"), false;
    if (client_->getConnInfo().isEncrypted()) return BLE_NOTE(Info, "already encrypted"), true;
    phase(Phase::Pairing);
    BLE_NOTE(Tx, "pairing request (bond, MITM, Secure Connections)");
    const bool ok = client_->secureConnection();
    phase(Phase::Idle);
    if (ok) refreshBonds();
    else BLE_NOTE(Bad, "pairing failed (%d): in pairing mode? forget it there too", client_->getLastError());
    return ok;
  }

  bool host() {
    if (!connected()) return BLE_NOTE(Warn, "connect first"), false;
    NimBLERemoteService *svc = client_->getService(NimBLEUUID(uint16_t(0x1812)));
    if (!svc) return BLE_NOTE(Warn, "no HID service (1812): not a keyboard or mouse"), false;
    if (!client_->getConnInfo().isEncrypted() && !pair()) return false;
    phase(Phase::Reading);
    hid.reset();
    // 1. The Report Map, usually 50-500 bytes: a long read over several packets.
    NimBLERemoteCharacteristic *mapChr = svc->getCharacteristic(NimBLEUUID(uint16_t(0x2A4B)));
    if (!mapChr) return BLE_NOTE(Bad, "no Report Map"), phase(Phase::Idle), false;
    const NimBLEAttValue m = mapChr->readValue();
    hid.setMap(m.data(), m.size());
    BLE_NOTE(Rx, "Report Map: %u bytes, %d input fields", m.size(), hid.map.count);
    if (hid.map.malformed) BLE_NOTE(Warn, "the Report Map ends mid-item: decoding what we can");
    // 2. Every input report, matched to its ID through descriptor 2908, then subscribed.
    if (!boot_) {
      setProtocol(svc, 1);
      for (NimBLERemoteCharacteristic *chr : svc->getCharacteristics(true)) {
        if (short16(chr->getUUID()) != 0x2A4D || !chr->canNotify()) continue;
        uint8_t id = 0, type = 1;
        if (NimBLERemoteDescriptor *ref = chr->getDescriptor(NimBLEUUID(uint16_t(0x2908)))) {
          const NimBLEAttValue v = ref->readValue();
          if (v.size() >= 2) id = v.data()[0], type = v.data()[1];
        }
        if (type != 1) continue;  // 1 input, 2 output (keyboard LEDs), 3 feature
        subscribe(chr, id, hid.kindOf(id));
      }
    } else {
      // 3. Boot protocol: fixed formats every BIOS understands; no Report Map needed.
      setProtocol(svc, 0);
      if (NimBLERemoteCharacteristic *k = svc->getCharacteristic(NimBLEUUID(uint16_t(0x2A22)))) subscribe(k, 0, ReportKind::BootKeyboard);
      if (NimBLERemoteCharacteristic *ms = svc->getCharacteristic(NimBLEUUID(uint16_t(0x2A33)))) subscribe(ms, 0, ReportKind::BootMouse);
    }
    bool kb = false, mouse = false, consumer = false;
    for (int i = 0; i < hid.routeCount; i++) {
      kb |= hid.routes[i].kind == ReportKind::Keyboard || hid.routes[i].kind == ReportKind::BootKeyboard;
      mouse |= hid.routes[i].kind == ReportKind::Mouse || hid.routes[i].kind == ReportKind::BootMouse;
      consumer |= hid.routes[i].kind == ReportKind::Consumer;
    }
    progress().edit([&](Progress &p) {
      p.phase = Phase::Hosting, p.since = millis();
      p.keyboard = kb, p.mouse = mouse, p.consumer = consumer, p.boot = boot_;
      p.fields = hid.map.count, p.mapBytes = int(m.size());
    });
    BLE_NOTE(Good, "hosting: %s%s%s%s", kb ? "keyboard " : "", mouse ? "mouse " : "", consumer ? "media keys" : "", boot_ ? " (boot)" : "");
    wantView = kb ? kViewKeyboard : mouse ? kViewMouse : -1;
    return true;
  }

  void setProtocol(NimBLERemoteService *svc, uint8_t mode) {
    // Protocol Mode (2A4E): 0 boot, 1 report. A standard HID setting on your own device.
    NimBLERemoteCharacteristic *pm = svc->getCharacteristic(NimBLEUUID(uint16_t(0x2A4E)));
    if (pm && pm->canWriteNoResponse()) pm->writeValue(&mode, 1, false);
    else if (mode == 0) BLE_NOTE(Warn, "no Protocol Mode: this device has no boot mode");
  }

  void subscribe(NimBLERemoteCharacteristic *chr, uint8_t id, ReportKind kind) {
    if (!hid.addRoute(chr->getHandle(), id, kind)) return;
    // Writes 01 00 into the characteristic's CCCD (2902): "send me notifications".
    const bool ok = chr->subscribe(true, [this](NimBLERemoteCharacteristic *c, uint8_t *data, size_t len, bool) { hid.onReport(c->getHandle(), data, len); });
    static const char *const kinds[] = {"keyboard", "mouse", "media", "other", "boot keyboard", "boot mouse"};
    if (ok) BLE_NOTE(Tx, "CCCD 01 00: report %u (%s)", id, kinds[static_cast<int>(kind)]);
    else BLE_NOTE(Bad, "subscribe to report %u refused", id);
  }

  static void formatValue(uint16_t u, const NimBLEAttValue &v, char *out, size_t n) {
    if (v.size() == 0) return void(strlcpy(out, "(empty)", n));
    if (u == 0x2A19) return void(snprintf(out, n, "%u %%", v.data()[0]));
    if (u == 0x2A01 && v.size() >= 2) {
      const uint16_t a = uint16_t(v.data()[0] | (v.data()[1] << 8));
      return void(snprintf(out, n, "%04X %s", a, ad::kindName(ad::kindFromAppearance(a))));
    }
    if (u == 0x2A50 && v.size() >= 7)
      return void(snprintf(out, n, "VID %04X PID %04X", v.data()[1] | (v.data()[2] << 8), v.data()[3] | (v.data()[4] << 8)));
    size_t i = 0;
    for (; i < v.size() && i + 1 < n; i++) out[i] = (v.data()[i] >= 0x20 && v.data()[i] < 0x7F) ? char(v.data()[i]) : '.';
    out[i] = 0;
  }

  static void add(Tree &t, uint8_t level, uint16_t uuid, const char *name, const char *value) {
    if (t.count == Tree::kMax) return void(t.truncated = true);
    Node &n = t.nodes[t.count++];
    n.level = level;
    n.uuid16 = uuid;
    strlcpy(n.name, name, sizeof(n.name));
    strlcpy(n.value, value, sizeof(n.value));
  }

  void refreshBonds() {
    const int n = std::min(NimBLEDevice::getNumBonds(), 4);
    portENTER_CRITICAL(&lock_);
    bondCount_ = 0;
    portEXIT_CRITICAL(&lock_);
    for (int i = 0; i < n; i++) {
      const NimBLEAddress a = NimBLEDevice::getBondedAddress(i);
      portENTER_CRITICAL(&lock_);
      memcpy(bonds_[bondCount_], a.getVal(), 6);
      bondTypes_[bondCount_++] = a.getType();
      portEXIT_CRITICAL(&lock_);
    }
  }

  NimBLEClient *client_ = nullptr;
  QueueHandle_t queue_ = nullptr;
  volatile bool busy_ = false, boot_ = false;
  volatile uint32_t lastAuto_ = 0;
  portMUX_TYPE lock_ = portMUX_INITIALIZER_UNLOCKED;
  uint8_t bonds_[4][6] = {};
  uint8_t bondTypes_[4] = {};
  int bondCount_ = 0;
};

}  // namespace b8

// What B8 knows, shared between three tasks:
//   the NimBLE task   heard devices (scan_table.h), notifications from the keyboard or mouse
//   the central task  connecting, discovering, pairing, reading the Report Map (it waits a lot)
//   loop()            draws it
// Each part has its own spinlock; loop() copies what the current view needs.
#pragma once

#include <Arduino.h>

namespace b8 {

enum class Phase : uint8_t { Idle, Connecting, Discovering, Pairing, Reading, Hosting };

inline const char *phaseName(Phase p) {
  static const char *const names[] = {"idle", "connecting", "discovering", "pairing", "reading the Report Map", "hosting"};
  return names[static_cast<int>(p)];
}

// ---- The GATT tree of the connected device --------------------------------------------------

struct Node {
  uint8_t level = 0;       // 0 service, 1 characteristic, 2 descriptor
  uint16_t uuid16 = 0;     // 0 = a 128-bit (vendor) UUID
  char name[24] = "";
  char value[28] = "";     // a read value, or why it wasn't read
  uint8_t props = 0;       // characteristics: 02 read, 04 write no rsp, 08 write, 10 notify, 20 indicate
};

struct Tree {
  static constexpr int kMax = 72;
  Node nodes[kMax];
  int count = 0;
  bool truncated = false;
  char device[24] = "";
  int services = 0, characteristics = 0;
  bool hasHid = false;
  bool vendorOnly = false;  // nothing but the GAP/GATT basics and the maker's own services
  bool audio = false;       // looks like a speaker or headphones (name, maker, appearance)
  uint32_t version = 0;
};

// ---- What the keyboard and mouse send ---------------------------------------------------------

enum class ReportKind : uint8_t { Keyboard, Mouse, Consumer, Other, BootKeyboard, BootMouse };

struct RawReport {
  uint32_t ms = 0;
  uint8_t id = 0;
  ReportKind kind = ReportKind::Other;
  uint8_t len = 0;
  uint8_t data[16] = {};
  char decoded[40] = "";
};

struct Stroke {
  int16_t x = 0, y = 0;
  uint8_t size = 0, colour = 0;
  bool down = false;
};

struct Input {
  static constexpr int kText = 400, kStrokes = 240, kTrail = 10, kReports = 6;
  // The little editor.
  uint8_t text[kText] = {};  // CP437, so ä ö ü ß show on the screen's built-in font
  int len = 0;
  uint8_t mods = 0;
  uint8_t held[8] = {};
  int heldN = 0;
  uint32_t keystrokes = 0;
  char media[20] = "";
  uint32_t mediaAt = 0;
  // The paint toy.
  int16_t mx = 160, my = 94;
  uint8_t buttons = 0, brush = 3, colour = 0;
  Stroke strokes[kStrokes];
  uint32_t strokeHead = 0;
  int16_t trailX[kTrail] = {}, trailY[kTrail] = {};
  uint32_t trailHead = 0;
  int16_t clickX = 0, clickY = 0;
  uint32_t clickAt = 0;
  uint32_t moves = 0;
  // Raw reports, newest last.
  RawReport reports[kReports];
  uint32_t reportHead = 0;
  uint32_t version = 0;
};

template <typename T>
class Guarded {
 public:
  template <typename F>
  void edit(F &&change) {
    portENTER_CRITICAL(&lock_);
    change(value_);
    value_.version++;
    portEXIT_CRITICAL(&lock_);
  }
  void copyTo(T &out) {
    portENTER_CRITICAL(&lock_);
    out = value_;
    portEXIT_CRITICAL(&lock_);
  }

 private:
  portMUX_TYPE lock_ = portMUX_INITIALIZER_UNLOCKED;
  T value_;
};

inline Guarded<Tree> &tree() {
  static Guarded<Tree> t;
  return t;
}
inline Guarded<Input> &input() {
  static Guarded<Input> i;
  return i;
}

// The central task's progress, for the screen.
struct Progress {
  Phase phase = Phase::Idle;
  char target[24] = "";
  uint32_t since = 0;
  bool keyboard = false, mouse = false, consumer = false, boot = false;
  int fields = 0, mapBytes = 0;
  uint32_t version = 0;
};

inline Guarded<Progress> &progress() {
  static Guarded<Progress> p;
  return p;
}

}  // namespace b8

// Turning a keyboard's or mouse's notifications into text and a moving cursor.
//
// After the central task has read the Report Map and subscribed, every key press arrives as a
// notification on one Report characteristic (2A4D). Which report it is comes from that
// characteristic's Report Reference descriptor (2908: report ID + type), not from the bytes: BLE
// leaves the report ID out of the value. The routes table maps characteristic handle -> report.
//
// onReport() runs in the NimBLE task: it only decodes and updates b8::input(), never draws.
#pragma once

#include <NimBLEDevice.h>

#include "ble_link.h"
#include "hid_report.h"
#include "host_state.h"
#include "ble_link.h"

namespace b8 {

struct Route {
  uint16_t handle = 0;
  uint8_t reportId = 0;
  ReportKind kind = ReportKind::Other;
};

class HidHost {
 public:
  static constexpr int kRoutes = 8;

  // Set by the central task BEFORE it subscribes, then only read: no lock needed for these.
  hid::Map map;
  hid::Keyboard keyboard;
  hid::Mouse mouse;
  int consumerField = -1;
  Route routes[kRoutes];
  int routeCount = 0;

  void reset() {
    map = hid::Map{};
    keyboard = hid::Keyboard{};
    mouse = hid::Mouse{};
    consumerField = -1;
    routeCount = 0;
    lastKeys_ = hid::KeyState{};
  }

  void setMap(const uint8_t *bytes, size_t n) {
    map = hid::parse(bytes, n);
    keyboard = hid::findKeyboard(map);
    mouse = hid::findMouse(map);
    consumerField = -1;
    for (int i = 0; i < map.count && consumerField < 0; i++)
      if (map.fields[i].page == hid::kPageConsumer && !map.fields[i].constant) consumerField = i;
  }

  // What a report ID carries, by the Report Map.
  ReportKind kindOf(uint8_t reportId) const {
    if (keyboard.found && keyboard.reportId == reportId) return ReportKind::Keyboard;
    if (mouse.found && mouse.reportId == reportId) return ReportKind::Mouse;
    if (consumerField >= 0 && map.fields[consumerField].reportId == reportId) return ReportKind::Consumer;
    return ReportKind::Other;
  }

  bool addRoute(uint16_t handle, uint8_t reportId, ReportKind kind) {
    if (routeCount == kRoutes) return false;
    routes[routeCount++] = Route{handle, reportId, kind};
    return true;
  }

  void setLayout(hid::Layout l) { layout_ = l; }
  hid::Layout layout() const { return layout_; }

  // NimBLE task: one notification.
  void onReport(uint16_t handle, const uint8_t *data, size_t len) {
    const Route *r = nullptr;
    for (int i = 0; i < routeCount; i++)
      if (routes[i].handle == handle) r = &routes[i];
    if (!r) return;
    ble::countRx(len);
    RawReport raw;
    raw.ms = millis();
    raw.id = r->reportId;
    raw.kind = r->kind;
    raw.len = uint8_t(std::min<size_t>(len, sizeof(raw.data)));
    memcpy(raw.data, data, raw.len);
    switch (r->kind) {
      case ReportKind::Keyboard: keys(hid::keyboardState(map, keyboard, data, len), raw); break;
      case ReportKind::BootKeyboard: keys(hid::bootKeyboard(data, len), raw); break;
      case ReportKind::Mouse: {
        uint8_t buttons = 0;
        for (int b = 0; b < mouse.buttonCount && b < 8; b++)
          if (hid::value(map.fields[mouse.buttons + b], data, len)) buttons |= uint8_t(1 << b);
        const int dx = hid::value(map.fields[mouse.x], data, len), dy = hid::value(map.fields[mouse.y], data, len);
        const int wheel = mouse.wheel >= 0 ? hid::value(map.fields[mouse.wheel], data, len) : 0;
        pointer(buttons, dx, dy, wheel, raw);
        break;
      }
      case ReportKind::BootMouse:
        if (len >= 3) pointer(data[0], int8_t(data[1]), int8_t(data[2]), len >= 4 ? int8_t(data[3]) : 0, raw);
        break;
      case ReportKind::Consumer: {
        const hid::Field &f = map.fields[consumerField];
        const int32_t usage = f.variable ? (hid::value(f, data, len) ? f.usage : 0) : hid::value(f, data, len);
        const char *name = hid::consumerName(uint16_t(usage));
        snprintf(raw.decoded, sizeof(raw.decoded), "media %s", usage ? (name ? name : "key") : "released");
        if (usage) {
          input().edit([&](Input &in) {
            snprintf(in.media, sizeof(in.media), "%s", name ? name : "media key");
            in.mediaAt = millis();
          });
          BLE_NOTE(Rx, "media key: %s (usage %02lX)", name ? name : "?", static_cast<unsigned long>(usage));
        }
        break;
      }
      case ReportKind::Other: snprintf(raw.decoded, sizeof(raw.decoded), "report %u: not decoded", r->reportId); break;
    }
    input().edit([&](Input &in) { in.reports[in.reportHead++ % Input::kReports] = raw; });
  }

 private:
  void keys(const hid::KeyState &now, RawReport &raw) {
    uint8_t fresh[8];
    const int n = hid::newlyPressed(lastKeys_, now, fresh);
    lastKeys_ = now;
    int at = snprintf(raw.decoded, sizeof(raw.decoded), "mods %02X", now.mods);
    for (int i = 0; i < now.n && at < int(sizeof(raw.decoded)) - 4; i++) at += snprintf(raw.decoded + at, sizeof(raw.decoded) - at, " %02X", now.keys[i]);
    const hid::Layout layout = layout_;
    input().edit([&](Input &in) {
      in.mods = now.mods;
      in.heldN = now.n;
      memcpy(in.held, now.keys, sizeof(in.held));
      for (int i = 0; i < n; i++) {
        const uint8_t code = fresh[i];
        in.keystrokes++;
        if (code == hid::key::kBackspace) {
          if (in.len) in.len--;
        } else if (code == hid::key::kEscape) {
          in.len = 0;
        } else if (const uint8_t c = hid::toChar(code, now.mods, layout)) {
          if (in.len == Input::kText) memmove(in.text, in.text + 40, in.len -= 40);  // full: drop the oldest line
          in.text[in.len++] = c == '\t' ? ' ' : c;
        }
      }
    });
  }

  void pointer(uint8_t buttons, int dx, int dy, int wheel, RawReport &raw) {
    snprintf(raw.decoded, sizeof(raw.decoded), "buttons %02X x %+d y %+d wheel %+d", buttons, dx, dy, wheel);
    input().edit([&](Input &in) {
      const uint8_t pressed = buttons & ~in.buttons;
      // Mice count in their own units (often 800+ per inch): halve, so the screen isn't crossed in a flick.
      in.mx = int16_t(std::max(2, std::min(317, in.mx + dx / 2)));
      in.my = int16_t(std::max(32, std::min(155, in.my + dy / 2)));
      if (wheel) in.brush = uint8_t(std::max(1, std::min(9, in.brush + (wheel > 0 ? 1 : -1))));
      if (pressed & 2) in.colour = uint8_t((in.colour + 1) % 6);  // right button: next colour
      if (pressed & 4) in.strokeHead = 0;                         // middle button: clear
      if (pressed) in.clickX = in.mx, in.clickY = in.my, in.clickAt = millis();
      if ((buttons & 1) || (in.buttons & 1)) {
        Stroke &s = in.strokes[in.strokeHead++ % Input::kStrokes];
        s = Stroke{in.mx, in.my, in.brush, in.colour, bool(buttons & 1)};
      }
      in.trailX[in.trailHead % Input::kTrail] = in.mx;
      in.trailY[in.trailHead++ % Input::kTrail] = in.my;
      in.buttons = buttons;
      in.moves++;
    });
  }

  hid::KeyState lastKeys_;
  volatile hid::Layout layout_ = hid::Layout::Us;
};

}  // namespace b8

// The shell every Bluetooth LE lab (B1-B8) shares: the screen with its status bar, the push button
// and BOOT, the on-board LED, serial commands, and printing the activity log.
//
// A lab is a BleLabSpec: its views (each one a draw function, plus what a double-click does there),
// its serial commands, and three hooks: setup() once NimBLE is running, tick() on every loop, and
// gesture() to give the button a lab-specific meaning. Each src/ble-lab-bN/main.cpp is that list.
//
// Button or BOOT, by default: click = next view · double-click = this view's action · long press =
// the lab's long action. While a numeric comparison waits: click = yes, long press = no.
// On-board LED, unless the lab claims it: breathing blue = advertising · cyan pulse = scanning ·
// steady blue = connected · violet = encrypted · amber blink = a passkey waits · white blink = data.
#pragma once

#include <Arduino.h>
#include <NimBLEDevice.h>

#include "ble_link.h"
#include "ble_views.h"
#include "button.h"
#include "display.h"
#include "pins.h"

class BleLab;

enum class Gesture : uint8_t { Click, DoubleClick, LongPress };

struct BleCommand {
  const char *name;  // the first word you type
  const char *args;  // for help, e.g. "<dBm>"
  const char *what;  // one line for help
  void (*run)(BleLab &lab, const String &arg, const String &lower);
};

struct BleView {
  const char *name;  // "radar"
  void (*draw)(BleLab &lab, FrameBuffer &fb, float t);
  const char *action;  // the command line a double-click runs on this view, or nullptr
};

struct BleLabSpec {
  const char *env;         // "ble-lab-b1"
  const char *id;          // "B1"
  const char *title;       // "Listen"
  const char *deviceName;  // what phones see: "Bench B3"
  const BleView *views;
  int viewCount;
  int startView;
  const BleCommand *commands;
  int commandCount;
  void (*setup)(BleLab &lab) = nullptr;  // after NimBLE is initialised
  void (*tick)(BleLab &lab) = nullptr;   // every loop, before drawing
  // First say on every gesture. Return true when handled, false for the default.
  bool (*gesture)(BleLab &lab, Gesture g, bool external) = nullptr;
  const char *longAction = nullptr;  // the command line a long press runs by default
};

class BleLab {
 public:
  explicit BleLab(const BleLabSpec &spec) : spec_(spec), view_(spec.startView) {}

  void begin() {
    Serial.begin(115200);
    delay(1500);
    if (!display_.begin()) {
      log_e("No memory for the frame buffer. Stopping.");
      return;
    }
    rgbLedWrite(PIN_RGB, 0, 0, 0);
    external_.begin();
    boot_.begin();
    if (!NimBLEDevice::init(spec_.deviceName)) {
      log_e("NimBLE did not start. Stopping.");
      return;
    }
    Serial.printf("\n%s: NimBLE %s up, address %s, TX power %d dBm\n", spec_.env, NimBLEDevice::getVersion(),
                  NimBLEDevice::getAddress().toString().c_str(), NimBLEDevice::getPower());
    if (spec_.setup) spec_.setup(*this);
    printHelp();
  }

  void loop() {
    FrameBuffer &fb = display_.fb();
    if (fb.pixels() == nullptr) {
      delay(1000);
      return;
    }
    pollSerial();
    handleButton(external_, true);
    handleButton(boot_, false);
    measureRssi();
    if (spec_.tick) spec_.tick(*this);
    link_ = ble::link().get();
    printActivity();
    showLed();

    const float t = millis() / 1000.0f;
    const BleView &v = spec_.views[view_];
    fb.fillScreen(pal::night);
    v.draw(*this, fb, t);
    if (passkeyShowing()) bv::passkey(fb, link_, t);
    bv::header(fb, spec_.id, v.name, view_, spec_.viewCount, link_, t);
    char hint[40];
    if (passkeyShowing() && link_.passkeyCompare) snprintf(hint, sizeof(hint), "click = yes, long = no");
    else if (v.action) snprintf(hint, sizeof(hint), "2x: %s", v.action);
    else snprintf(hint, sizeof(hint), "click: next view");
    bv::footer(fb, hint);
    display_.push();
  }

  // ---- For views and commands ------------------------------------------------------------------

  const ble::LinkState &state() const { return link_; }
  const BleLabSpec &spec() const { return spec_; }
  int view() const { return view_; }

  void setView(int v) {
    view_ = (v % spec_.viewCount + spec_.viewCount) % spec_.viewCount;
    log_i("view %d: %s", view_ + 1, spec_.views[view_].name);
  }
  void showView(const char *name) {
    for (int i = 0; i < spec_.viewCount; i++)
      if (strcmp(spec_.views[i].name, name) == 0) return setView(i);
  }

  // The lab drives the on-board LED itself (B3's LED characteristic); false hands it back.
  void claimLed(bool claimed) {
    ledClaimed_ = claimed;
    ledShown_ = 0xFFFFFFFF;
  }

  // log_w is a macro that can't be returned from a void function; this can.
  [[gnu::format(printf, 2, 3)]] void warn(const char *fmt, ...) {
    char text[120];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(text, sizeof(text), fmt, ap);
    va_end(ap);
    log_w("%s", text);
  }

  // Parse a number argument; false when it is missing, not a number or out of range.
  static bool number(const String &arg, long lo, long hi, long &out) {
    if (arg.isEmpty()) return false;
    for (size_t i = 0; i < arg.length(); i++)
      if (!isDigit(arg[i]) && !(i == 0 && arg[i] == '-')) return false;
    out = arg.toInt();
    return out >= lo && out <= hi;
  }

  void runLine(const String &raw) {
    String line = raw;
    line.trim();
    if (line.isEmpty()) return;
    const int sp = line.indexOf(' ');
    String cmd = sp < 0 ? line : line.substring(0, sp);
    String arg = sp < 0 ? String() : line.substring(sp + 1);
    cmd.toLowerCase();
    arg.trim();
    String lower = arg;
    lower.toLowerCase();
    if (cmd == "help" || cmd == "?") return printHelp();
    if (cmd == "view") {
      long n = 0;
      if (!number(arg, 1, spec_.viewCount, n)) return warn("view <1-%d>", spec_.viewCount);
      return setView(n - 1);
    }
    if (cmd == "status") return printStatus();
    if (cmd == "power") return power(arg);
    for (int i = 0; i < spec_.commandCount; i++)
      if (cmd == spec_.commands[i].name) return spec_.commands[i].run(*this, arg, lower);
    log_w("unknown command '%s' in %s (type help)", line.c_str(), spec_.env);
  }

 private:
  bool passkeyShowing() const { return link_.passkey != 0 && millis() - link_.passkeySince < 30000; }

  void printHelp() {
    Serial.printf("\nBluetooth lab %s %s  (%s)  ·  phones see \"%s\"\n", spec_.id, spec_.title, spec_.env, spec_.deviceName);
    for (int i = 0; i < spec_.commandCount; i++) {
      const BleCommand &c = spec_.commands[i];
      char usage[40];
      snprintf(usage, sizeof(usage), "%s %s", c.name, c.args);
      Serial.printf("  %-28s %s\n", usage, c.what);
    }
    Serial.printf("  %-28s %s\n", "status", "the radio, the link and its security, in detail");
    Serial.printf("  %-28s %s\n", "power <dBm>", "transmit power: -24 to 20 (default 9)");
    Serial.printf("  %-28s %s\n", "view <n>", "show screen view n");
    Serial.print("Views:");
    for (int i = 0; i < spec_.viewCount; i++)
      Serial.printf(" %d %s%s", i + 1, spec_.views[i].name, i + 1 < spec_.viewCount ? " ·" : "\n");
    Serial.println("Button (GPIO 5, optional) or BOOT: click = next view, double-click = the view's action");
  }

  void printStatus() {
    const ble::LinkState s = ble::link().get();
    Serial.printf("radio %s · this board %s · TX power %d dBm\n", ble::radioName(s.radio), NimBLEDevice::getAddress().toString().c_str(),
                  NimBLEDevice::getPower());
    if (s.radio != ble::Radio::Connected) {
      if (s.lastDisconnect >= 0) Serial.printf("last link ended: 0x%02X %s\n", s.lastDisconnect & 0xFF, ble::disconnectReason(s.lastDisconnect));
      return;
    }
    const ble::Peer &p = s.peer;
    Serial.printf("peer %s%s%s (%s) · we are the %s\n", p.addr, p.idAddr[0] ? " id " : "", p.idAddr, p.name[0] ? p.name : "no name",
                  p.central ? "peripheral" : "central");
    Serial.printf("interval %.2f ms · latency %u · timeout %u ms · MTU %u · PHY %u/%u · RSSI %d dBm\n", p.interval * 1.25f, p.latency,
                  p.timeout * 10, p.mtu, p.txPhy, p.rxPhy, p.rssi);
    Serial.printf("security: %s, %s, %s, key %u bytes\n", p.encrypted ? "encrypted" : "not encrypted",
                  p.authenticated ? "authenticated (MITM)" : "not authenticated", p.bonded ? "bonded" : "not bonded", p.keySize);
    Serial.printf("traffic: rx %lu ops / %lu B · tx %lu ops / %lu B\n", static_cast<unsigned long>(s.rxOps), static_cast<unsigned long>(s.rxBytes),
                  static_cast<unsigned long>(s.txOps), static_cast<unsigned long>(s.txBytes));
  }

  void power(const String &arg) {
    long dbm = 0;
    if (!number(arg, -24, 20, dbm)) return warn("power <dBm>, -24 to 20. Now %d dBm", NimBLEDevice::getPower());
    if (!NimBLEDevice::setPower(int8_t(dbm))) return warn("the radio refused %ld dBm", dbm);
    BLE_NOTE(Info, "TX power %d dBm", NimBLEDevice::getPower());
  }

  void pollSerial() {
    static String buffer;
    while (Serial.available()) {
      const char c = Serial.read();
      if (c == '\n' || c == '\r') {
        if (!buffer.isEmpty()) runLine(buffer);
        buffer = "";
      } else if (c == 0x08 || c == 0x7F) {
        if (!buffer.isEmpty()) buffer.remove(buffer.length() - 1);
      } else if (uint8_t(c) < 0x20) {
        // Other control characters (arrow keys send escape sequences): ignore.
      } else if (buffer.length() < 120) {
        buffer += c;
      }
    }
  }

  void handleButton(Button &b, bool external) {
    Gesture g;
    switch (b.poll()) {
      case Button::Event::Click: g = Gesture::Click; break;
      case Button::Event::DoubleClick: g = Gesture::DoubleClick; break;
      case Button::Event::LongPress: g = Gesture::LongPress; break;
      default: return;
    }
    if (spec_.gesture && spec_.gesture(*this, g, external)) return;
    switch (g) {
      case Gesture::Click: setView(view_ + 1); break;
      case Gesture::DoubleClick:
        if (spec_.views[view_].action) {
          Serial.printf("> %s   (double-click)\n", spec_.views[view_].action);
          runLine(spec_.views[view_].action);
        }
        break;
      case Gesture::LongPress:
        if (spec_.longAction) {
          Serial.printf("> %s   (long press)\n", spec_.longAction);
          runLine(spec_.longAction);
        }
        break;
    }
  }

  // RSSI of a live link: the controller measures it on every connection event; we ask once a second.
  void measureRssi() {
    const ble::LinkState &s = link_;
    if (s.radio != ble::Radio::Connected || millis() - rssiAt_ < 1000) return;
    rssiAt_ = millis();
    int8_t rssi = 0;
    if (ble_gap_conn_rssi(s.peer.handle, &rssi) == 0) ble::link().edit([&](ble::LinkState &st) { st.peer.rssi = rssi; });
  }

  // New activity lines go to serial from here, in order, never from the NimBLE task.
  void printActivity() {
    ble::Activity &a = ble::activity();
    const uint32_t head = a.head();
    if (printed_ + ble::Activity::kSize < head) {
      Serial.printf("  ... %lu lines skipped\n", static_cast<unsigned long>(head - ble::Activity::kSize - printed_));
      printed_ = head - ble::Activity::kSize;
    }
    ble::ActEntry e;
    for (; printed_ < head; printed_++)
      if (a.get(printed_, e)) Serial.printf("  %s %s\n", bv::actMark(e.kind), e.text);
  }

  void showLed() {
    if (ledClaimed_) return;
    const uint32_t now = millis();
    const uint32_t traffic = link_.rxOps + link_.txOps;
    if (traffic != traffic_) traffic_ = traffic, flashUntil_ = now + 60;
    // Brightness in 12 steps, so the LED (a whole WS2812 frame per write) is only rewritten on a change.
    const float wave = 0.5f + 0.5f * sinf(now / 1000.0f * 3.1416f);
    const uint8_t breathe = uint8_t(int(wave * 11) * 8 + 6);
    uint8_t r = 0, g = 0, b = 0;
    if (passkeyShowing()) r = (now / 250) & 1 ? 120 : 0, g = r / 2;
    else if (now < flashUntil_) r = 120, g = 120, b = 120;
    else switch (link_.radio) {
      case ble::Radio::Off: break;
      case ble::Radio::Scanning: g = breathe / 2, b = breathe / 2; break;
      case ble::Radio::Advertising: b = breathe; break;
      case ble::Radio::Connecting: r = 60, g = 40; break;
      case ble::Radio::Connected:
        if (link_.peer.encrypted) r = 50, b = 90;
        else b = 90;
        break;
    }
    const uint32_t colour = (uint32_t(r) << 16) | (uint32_t(g) << 8) | b;
    if (colour == ledShown_) return;
    ledShown_ = colour;
    rgbLedWrite(PIN_RGB, r, g, b);
  }

  const BleLabSpec &spec_;
  Display display_;
  Button external_{PIN_BUTTON, "button"};
  Button boot_{PIN_BOOT_BTN, "BOOT"};
  ble::LinkState link_;
  int view_;
  bool ledClaimed_ = false;
  uint32_t ledShown_ = 0xFFFFFFFF, flashUntil_ = 0, traffic_ = 0, rssiAt_ = 0, printed_ = 0;
};

// Drawing pieces every BLE lab shares (320 x 170, landscape):
//   header   "BLE" + the view's name, view dots, and the status cluster: what the radio is doing,
//            a lock when the link is encrypted, a key when the peer is bonded, signal bars
//   footer   the button hint on the left, the latest activity line on the right
//   link     a live connection: who is central, the connection events ticking, MTU, PHY, security
//   log      the activity log, newest at the bottom
//   passkey  the big 6 digits, drawn over any view while pairing waits for you
#pragma once

#include <Fonts/FreeSans9pt7b.h>
#include <Fonts/FreeSansBold24pt7b.h>
#include <Fonts/FreeSansBold9pt7b.h>
#include <math.h>

#include "ble_link.h"
#include "color.h"
#include "frame_buffer.h"

namespace bv {

constexpr int kW = 320, kH = 170, kTop = 30, kBottom = kH - 12;
// Bluetooth's own colours on the bench palette: blue = radio, violet = encrypted.
constexpr uint16_t kBlue = rgb(80, 150, 255);
constexpr uint16_t kViolet = rgb(176, 130, 255);
constexpr uint16_t kPanel = rgb(20, 28, 40);

inline int textWidth(FrameBuffer &fb, const char *s) {
  int16_t x1, y1;
  uint16_t w, h;
  fb.getTextBounds(s, 0, 0, &x1, &y1, &w, &h);
  return w;
}

inline void small(FrameBuffer &fb, int x, int y, uint16_t c, const char *s) {
  fb.setFont(nullptr);
  fb.setTextColor(c);
  fb.setCursor(x, y);
  fb.print(s);
}

inline void bold(FrameBuffer &fb, int x, int y, uint16_t c, const char *s) {
  fb.setFont(&FreeSansBold9pt7b);
  fb.setTextColor(c);
  fb.setCursor(x, y);
  fb.print(s);
}

// A label over a value, in a column.
inline void stat(FrameBuffer &fb, int x, int y, const char *label, const char *value, uint16_t c = pal::ink) {
  small(fb, x, y, pal::muted, label);
  bold(fb, x, y + 22, c, value);
}

// Four bars, like a phone's: -50 dBm and up = 4 bars, -90 and below = 0.
inline void signalBars(FrameBuffer &fb, int x, int y, int rssi, uint16_t on = pal::ink) {
  const int bars = rssi == 0 ? 0 : rssi >= -55 ? 4 : rssi >= -67 ? 3 : rssi >= -78 ? 2 : rssi >= -90 ? 1 : 0;
  for (int i = 0; i < 4; i++) {
    const int h = 3 + i * 3;
    fb.fillRect(x + i * 4, y + 12 - h, 3, h, i < bars ? on : pal::dim);
  }
}

inline uint16_t rssiColour(int rssi) { return rssi >= -67 ? pal::teal : rssi >= -82 ? pal::amber : pal::coral; }

inline void lockIcon(FrameBuffer &fb, int x, int y, uint16_t c) {
  fb.drawRoundRect(x + 2, y, 7, 7, 3, c);
  fb.fillRect(x, y + 5, 11, 8, c);
}

inline void keyIcon(FrameBuffer &fb, int x, int y, uint16_t c) {
  fb.drawCircle(x + 3, y + 6, 3, c);
  fb.drawFastHLine(x + 6, y + 6, 7, c);
  fb.drawFastVLine(x + 11, y + 6, 4, c);
  fb.drawFastVLine(x + 9, y + 6, 3, c);
}

// The radio's state as a small animated glyph centred on (x, y).
inline void radioGlyph(FrameBuffer &fb, int x, int y, ble::Radio r, float t) {
  switch (r) {
    case ble::Radio::Off: fb.drawCircle(x, y, 5, pal::dim); break;
    case ble::Radio::Scanning: {
      // A radar sweep: we are listening.
      fb.drawCircle(x, y, 7, pal::dim);
      const float a = t * 5.0f;
      fb.drawLine(x, y, x + int(cosf(a) * 7), y + int(sinf(a) * 7), pal::teal);
      fb.fillCircle(x, y, 1, pal::teal);
      break;
    }
    case ble::Radio::Advertising: {
      // Rings leaving the antenna: we are shouting.
      fb.fillCircle(x, y, 2, kBlue);
      for (int i = 0; i < 2; i++) {
        const float k = fmodf(t * 1.2f + i * 0.5f, 1.0f);
        fb.drawCircle(x, y, 3 + int(k * 6), mix(kBlue, pal::night, uint8_t(k * 255)));
      }
      break;
    }
    case ble::Radio::Connecting:
      fb.drawCircle(x, y, 6, (int(t * 6) & 1) ? pal::amber : pal::dim);
      break;
    case ble::Radio::Connected:
      // Two linked rings: a connection.
      fb.drawCircle(x - 3, y, 4, kBlue);
      fb.drawCircle(x + 3, y, 4, kBlue);
      break;
  }
}

inline void header(FrameBuffer &fb, const char *labId, const char *view, int index, int count, const ble::LinkState &s, float t) {
  fb.setFont(&FreeSansBold9pt7b);
  fb.setTextColor(kBlue);
  fb.setCursor(8, 18);
  fb.print(labId);
  fb.print(" ");
  fb.setFont(&FreeSans9pt7b);
  fb.setTextColor(pal::muted);
  fb.print(view);
  // Status cluster, right to left: signal, key, lock, radio.
  int x = 302;
  if (s.radio == ble::Radio::Connected && s.peer.rssi != 0) signalBars(fb, x, 9, s.peer.rssi, rssiColour(s.peer.rssi));
  x -= 18;
  if (s.peer.bonded && s.radio == ble::Radio::Connected) keyIcon(fb, x, 8, pal::amber), x -= 18;
  if (s.peer.encrypted && s.radio == ble::Radio::Connected) lockIcon(fb, x + 2, 7, kViolet), x -= 16;
  radioGlyph(fb, x + 4, 15, s.radio, t);
  const int firstDot = x - 14 - (count - 1) * 9;
  for (int i = 0; i < count; i++) fb.fillCircle(firstDot + i * 9, 15, 3, i == index ? pal::ink : pal::dim);
  fb.drawFastHLine(0, 28, kW, pal::dim);
}

inline uint16_t actColour(ble::Act k) {
  switch (k) {
    case ble::Act::Good: return pal::teal;
    case ble::Act::Warn: return pal::amber;
    case ble::Act::Bad: return pal::coral;
    case ble::Act::Rx: return kBlue;
    case ble::Act::Tx: return kViolet;
    default: return pal::muted;
  }
}

inline const char *actMark(ble::Act k) {
  switch (k) {
    case ble::Act::Good: return "+";
    case ble::Act::Warn: return "!";
    case ble::Act::Bad: return "x";
    case ble::Act::Rx: return "<";
    case ble::Act::Tx: return ">";
    default: return "-";
  }
}

// Left: the button hint. Right: the newest activity line, fading after 6 s.
inline void footer(FrameBuffer &fb, const char *hint) {
  fb.fillRect(0, kH - 11, kW, 11, pal::night);
  small(fb, 6, kH - 9, pal::muted, hint);
  ble::Activity &a = ble::activity();
  ble::ActEntry e;
  const uint32_t head = a.head();
  if (head == 0 || !a.get(head - 1, e)) return;
  const uint32_t age = millis() - e.ms;
  if (age > 6000) return;
  char right[30];
  strlcpy(right, e.text, sizeof(right));
  fb.setFont(nullptr);
  const uint16_t c = mix(actColour(e.kind), pal::night, uint8_t(age > 4000 ? (age - 4000) * 200 / 2000 : 0));
  small(fb, kW - 6 - textWidth(fb, right), kH - 9, c, right);
}

// ---- log ----------------------------------------------------------------------------------------

inline void log(FrameBuffer &fb, int y0 = kTop + 4, int rows = 10) {
  ble::Activity &a = ble::activity();
  const uint32_t head = a.head();
  if (head == 0) {
    small(fb, 8, y0 + 4, pal::muted, "Nothing on the air yet.");
    return;
  }
  const uint32_t from = head > uint32_t(rows) ? head - rows : 0;
  ble::ActEntry e;
  int y = y0;
  for (uint32_t i = from; i < head; i++, y += 12) {
    if (!a.get(i, e)) continue;
    char when[12];
    snprintf(when, sizeof(when), "%5lu.%lu", static_cast<unsigned long>(e.ms / 1000), static_cast<unsigned long>(e.ms / 100 % 10));
    small(fb, 4, y, pal::dim, when);
    small(fb, 50, y, actColour(e.kind), actMark(e.kind));
    char text[44];
    strlcpy(text, e.text, sizeof(text));
    small(fb, 60, y, i + 1 == head ? pal::ink : pal::muted, text);
  }
}

// ---- link ---------------------------------------------------------------------------------------

// The connection drawn as two devices and the connection events between them: one exchange every
// interval, the dot's speed is real time slowed down 20x so 7.5-50 ms intervals stay visible.
inline void link(FrameBuffer &fb, const ble::LinkState &s, float t, const char *usLabel = "this board", const char *themLabel = nullptr) {
  const bool up = s.radio == ble::Radio::Connected;
  const int ly = 62, lx = 30, rx = 150;
  fb.fillRoundRect(lx - 22, ly - 22, 44, 44, 6, kPanel);
  fb.drawRoundRect(lx - 22, ly - 22, 44, 44, 6, kBlue);
  fb.fillRoundRect(rx - 16, ly - 26, 32, 52, 6, kPanel);
  fb.drawRoundRect(rx - 16, ly - 26, 32, 52, 6, up ? kBlue : pal::dim);
  small(fb, lx - 18, ly + 28, pal::muted, usLabel);
  small(fb, rx - 18, ly + 28, pal::muted, themLabel ? themLabel : (up && s.peer.name[0] ? s.peer.name : "peer"));
  // Who leads: the central sets the timing, the peripheral answers in each event.
  small(fb, lx - 18, ly - 4, pal::ink, s.peer.central || !up ? "periph" : "central");
  small(fb, rx - 14, ly - 4, up ? pal::ink : pal::dim, s.peer.central ? "central" : "periph");
  if (up) {
    const float intervalMs = s.peer.interval * 1.25f;
    const float period = fmaxf(intervalMs * 20.0f / 1000.0f, 0.15f);
    const float k = fmodf(t, period) / period;
    const int x = lx + 24 + int(k * (rx - lx - 42));
    fb.drawFastHLine(lx + 24, ly - 6, rx - lx - 42, pal::dim);
    fb.drawFastHLine(lx + 24, ly + 6, rx - lx - 42, pal::dim);
    fb.fillCircle(x, ly - 6, 3, s.peer.encrypted ? kViolet : kBlue);
    fb.fillCircle(lx + 24 + (rx - lx - 42) - (x - lx - 24), ly + 6, 3, pal::teal);
    if (s.peer.encrypted) lockIcon(fb, (lx + rx) / 2 - 5, ly - 26, kViolet);
  } else {
    small(fb, lx + 30, ly - 3, pal::muted, s.advertising ? "waiting..." : "no link");
  }

  char v[40];
  const int cx = 190;
  if (!up) {
    stat(fb, cx, 38, "last link ended", s.lastDisconnect < 0 ? "-" : "", pal::muted);
    if (s.lastDisconnect >= 0) {
      snprintf(v, sizeof(v), "reason 0x%02X", s.lastDisconnect & 0xFF);
      bold(fb, cx, 60, pal::ink, v);
      char why[34];
      strlcpy(why, ble::disconnectReason(s.lastDisconnect), sizeof(why));
      small(fb, cx, 68, pal::muted, why);
    }
    return;
  }
  snprintf(v, sizeof(v), "%.2f ms", s.peer.interval * 1.25f);
  stat(fb, cx, 34, "interval", v, kBlue);
  snprintf(v, sizeof(v), "%u B", s.peer.mtu);
  stat(fb, cx + 74, 34, "MTU", v);
  snprintf(v, sizeof(v), "%u", s.peer.latency);
  stat(fb, cx, 70, "latency", v);
  snprintf(v, sizeof(v), "%u ms", s.peer.timeout * 10);
  stat(fb, cx + 74, 70, "timeout", v);
  static const char *const phy[] = {"?", "1M", "2M", "Coded"};
  snprintf(v, sizeof(v), "%s/%s", phy[s.peer.txPhy & 3], phy[s.peer.rxPhy & 3]);
  stat(fb, cx, 106, "PHY tx/rx", v);
  snprintf(v, sizeof(v), "%d dBm", s.peer.rssi);
  stat(fb, cx + 74, 106, "RSSI", s.peer.rssi ? v : "-", s.peer.rssi ? rssiColour(s.peer.rssi) : pal::muted);
  // Security row under the drawing.
  const uint16_t sc = s.peer.encrypted ? kViolet : pal::muted;
  snprintf(v, sizeof(v), "%s%s%s", s.peer.encrypted ? "encrypted" : "plain text", s.peer.authenticated ? " + MITM" : "", s.peer.bonded ? " + bonded" : "");
  small(fb, 8, 114, sc, v);
  snprintf(v, sizeof(v), "%s  up %lus", s.peer.addr, static_cast<unsigned long>((millis() - s.connectedAt) / 1000));
  small(fb, 8, 126, pal::muted, v);
  snprintf(v, sizeof(v), "rx %lu ops %lu B", static_cast<unsigned long>(s.rxOps), static_cast<unsigned long>(s.rxBytes));
  small(fb, 8, 138, kBlue, v);
  snprintf(v, sizeof(v), "tx %lu ops %lu B", static_cast<unsigned long>(s.txOps), static_cast<unsigned long>(s.txBytes));
  small(fb, 8, 148, kViolet, v);
}

// ---- passkey ------------------------------------------------------------------------------------

// Drawn over the current view while pairing waits for a person.
inline void passkey(FrameBuffer &fb, const ble::LinkState &s, float t) {
  fb.fillRoundRect(16, 34, kW - 32, 118, 10, kPanel);
  fb.drawRoundRect(16, 34, kW - 32, 118, 10, (int(t * 2) & 1) ? pal::amber : kViolet);
  small(fb, 30, 44, pal::amber, s.passkeyCompare ? "NUMERIC COMPARISON" : "PASSKEY ENTRY");
  small(fb, 30, 56, pal::muted, s.passkeyCompare ? "Same number on the other screen?" : "Type this on the other device:");
  char digits[8];
  snprintf(digits, sizeof(digits), "%06lu", static_cast<unsigned long>(s.passkey));
  fb.setFont(&FreeSansBold24pt7b);
  fb.setTextColor(pal::ink);
  const int w = textWidth(fb, digits);
  fb.setCursor((kW - w) / 2, 112);
  fb.print(digits);
  const uint32_t left = 30 - min<uint32_t>(30, (millis() - s.passkeySince) / 1000);
  fb.fillRect(30, 124, (kW - 60) * left / 30, 3, pal::amber);
  small(fb, 30, 134, pal::muted, s.passkeyCompare ? "click = yes, it matches   long press = no" : "the other side has 30 s");
}

}  // namespace bv

// What every BLE lab knows about its radio, shared between two tasks.
//
// NimBLE runs its own task (the "host", on core 0). Every callback it makes (a device was heard,
// a phone connected, a value was written) runs there. The screen and serial run in loop() on
// core 1. So the callbacks never draw or print: they update this state and push a line into the
// activity log, and loop() takes a copy to show it. A spinlock guards each copy (a few hundred
// bytes, microseconds), the same idea as the RFID labs' reader snapshot.
#pragma once

#include <Arduino.h>
#include <freertos/FreeRTOS.h>

#include <stdarg.h>

namespace ble {

// What the radio is doing right now, for the status bar and the on-board LED.
enum class Radio : uint8_t { Off, Scanning, Advertising, Connecting, Connected };

inline const char *radioName(Radio r) {
  static const char *const names[] = {"off", "scanning", "advertising", "connecting", "connected"};
  return names[static_cast<int>(r)];
}

// The other side of a connection: a phone, a laptop, a keyboard.
struct Peer {
  char addr[18] = "";        // as the radio sees it right now (may be a private, changing address)
  char idAddr[18] = "";      // the identity address, once bonding revealed it
  char name[24] = "";        // when we know it (scan response, GAP name, or B8's discovery)
  uint8_t addrType = 0;      // 0 public, 1 random
  uint16_t handle = 0xFFFF;  // connection handle
  uint16_t mtu = 23;         // bytes per ATT packet; 23 until both sides agree on more
  uint16_t interval = 0;     // connection interval, in 1.25 ms units
  uint16_t latency = 0;      // events the peripheral may skip
  uint16_t timeout = 0;      // supervision timeout, in 10 ms units
  uint8_t txPhy = 1, rxPhy = 1;  // 1 = 1M, 2 = 2M, 3 = Coded
  int8_t rssi = 0;           // measured on the live connection (0 = not measured yet)
  bool encrypted = false, authenticated = false, bonded = false;
  uint8_t keySize = 0;
  bool central = false;      // true when the PEER is the central (we are the peripheral)
};

struct LinkState {
  Radio radio = Radio::Off;
  bool advertising = false;
  bool scanning = false;
  uint8_t connections = 0;
  Peer peer;                     // the most recent connection
  uint32_t connectedAt = 0;      // millis()
  int lastDisconnect = -1;       // reason code of the last disconnect, -1 = none yet
  uint32_t rxOps = 0, txOps = 0;      // writes/reads received, notifications/indications sent
  uint32_t rxBytes = 0, txBytes = 0;
  uint32_t passkey = 0;          // non-zero while a passkey is on screen (B4, B8)
  bool passkeyCompare = false;   // true = numeric comparison (press to accept), false = type it in
  uint32_t passkeySince = 0;
  uint32_t version = 0;          // bumps on every change
};

// The shared state, one per program. Callbacks call ble::link().edit([](LinkState &s){ ... }).
class Link {
 public:
  template <typename F>
  void edit(F &&change) {
    portENTER_CRITICAL(&lock_);
    change(state_);
    state_.version++;
    portEXIT_CRITICAL(&lock_);
  }
  LinkState get() {
    portENTER_CRITICAL(&lock_);
    LinkState copy = state_;
    portEXIT_CRITICAL(&lock_);
    return copy;
  }

 private:
  portMUX_TYPE lock_ = portMUX_INITIALIZER_UNLOCKED;
  LinkState state_;
};

inline Link &link() {
  static Link l;
  return l;
}

// Every operation that crosses the air, for the traffic counters on the link view.
inline void countRx(size_t bytes) {
  link().edit([&](LinkState &s) { s.rxOps++, s.rxBytes += bytes; });
}
inline void countTx(size_t bytes) {
  link().edit([&](LinkState &s) { s.txOps++, s.txBytes += bytes; });
}

// ---- The activity log ------------------------------------------------------------------------
// Every lab writes what happens on the air here: "→ notify button click", "← write LED ff8000".
// loop() prints new lines to serial and the log view draws the last few.

enum class Act : uint8_t { Info, Good, Warn, Bad, Rx, Tx };

struct ActEntry {
  uint32_t ms = 0;
  Act kind = Act::Info;
  char text[60] = "";
};

class Activity {
 public:
  static constexpr int kSize = 32;

  [[gnu::format(printf, 3, 4)]] void add(Act kind, const char *fmt, ...) {
    ActEntry e;
    e.ms = millis();
    e.kind = kind;
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(e.text, sizeof(e.text), fmt, ap);  // formatted outside the lock
    va_end(ap);
    portENTER_CRITICAL(&lock_);
    ring_[head_ % kSize] = e;
    head_++;
    portEXIT_CRITICAL(&lock_);
  }

  uint32_t head() {
    portENTER_CRITICAL(&lock_);
    const uint32_t h = head_;
    portEXIT_CRITICAL(&lock_);
    return h;
  }

  // Entry number i (0 = the first ever). False when it has already been overwritten.
  bool get(uint32_t i, ActEntry &out) {
    portENTER_CRITICAL(&lock_);
    const bool ok = i < head_ && head_ - i <= kSize;
    if (ok) out = ring_[i % kSize];
    portEXIT_CRITICAL(&lock_);
    return ok;
  }

 private:
  portMUX_TYPE lock_ = portMUX_INITIALIZER_UNLOCKED;
  ActEntry ring_[kSize];
  uint32_t head_ = 0;
};

inline Activity &activity() {
  static Activity a;
  return a;
}

// Short names for the callbacks.
#define BLE_NOTE(kind, ...) ::ble::activity().add(::ble::Act::kind, __VA_ARGS__)

// Why a link ended, in words. NimBLE reports HCI reasons as 0x200 + the HCI code.
inline const char *disconnectReason(int reason) {
  switch (reason & 0xFF) {
    case 0x08: return "timeout: the peer went out of range or stopped answering";
    case 0x13: return "the peer hung up";
    case 0x16: return "we hung up";
    case 0x3B: return "unacceptable connection parameters";
    case 0x3D: return "MIC failure (encryption keys did not match)";
    case 0x3E: return "the connection never got established";
    case 0x05: return "authentication failure (forgotten bond on one side?)";
    case 0x06: return "PIN or key missing (forgotten bond on one side?)";
    default: return "other";
  }
}

}  // namespace ble

// A push button on any GPIO, wired between the pin and GND.
//
// Wiring: we turn on the chip's internal pull-up resistor, so the pin reads HIGH when the
// button is up and LOW when pressed (the button connects it to GND). No resistor needed.
//
// Bounce: the metal contacts inside a button flicker on/off for a few milliseconds on
// every press and release. Our screen loop only looks about 22 times a second, far too
// slowly to see that. So an interrupt counts every single edge the instant it happens,
// and poll() only trusts a new state once the pin has been quiet for kDebounceMs.
//
// Gestures, reported by poll():
//   Click        press and release, then nothing else for kDoubleGapMs
//   DoubleClick  two clicks within kDoubleGapMs
//   LongPress    held for kLongPressMs (fires while still held, so it feels instant)
#pragma once

#include <Arduino.h>
#include <esp_timer.h>

class Button {
 public:
  enum class Event { None, Click, DoubleClick, LongPress };

  Button(uint8_t pin, const char *name) : pin_(pin), name_(name) {}

  void begin() {
    pinMode(pin_, INPUT_PULLUP);
    // CHANGE = run onEdge on every rising and falling edge, bounces included.
    attachInterruptArg(digitalPinToInterrupt(pin_), onEdge, this, CHANGE);
  }

  const char *name() const { return name_; }
  bool isDown() const { return pressed_; }
  // Raw edges seen during the last press + release, minus the 2 a perfect button makes.
  uint32_t lastBounces() const { return lastBounces_; }

  Event poll() {
    const uint32_t nowUs = uint32_t(esp_timer_get_time());
    const uint32_t now = millis();

    // 1. Debounce: accept the pin's level once no edge has arrived for kDebounceMs.
    const bool level = digitalRead(pin_) == LOW;
    if (level != pressed_ && nowUs - lastEdgeUs_ >= kDebounceMs * 1000) {
      pressed_ = level;
      if (pressed_) {
        pressedAt_ = now;
        longFired_ = false;
      } else {
        // Every edge since the previous release belongs to this press + release.
        const uint32_t edges = edges_ - edgesAtRest_;
        edgesAtRest_ = edges_;
        lastBounces_ = edges > 2 ? edges - 2 : 0;
        if (!longFired_) {
          clicks_++;
          releasedAt_ = now;
        }
      }
    }

    // 2. Turn clean presses into gestures.
    if (pressed_ && !longFired_ && now - pressedAt_ >= kLongPressMs) {
      longFired_ = true;
      clicks_ = 0;
      return Event::LongPress;
    }
    if (!pressed_ && clicks_ >= 2) {
      clicks_ = 0;
      return Event::DoubleClick;
    }
    if (!pressed_ && clicks_ == 1 && now - releasedAt_ >= kDoubleGapMs) {
      clicks_ = 0;
      return Event::Click;
    }
    return Event::None;
  }

 private:
  static constexpr uint32_t kDebounceMs = 25;
  static constexpr uint32_t kLongPressMs = 600;
  static constexpr uint32_t kDoubleGapMs = 280;

  // Runs inside the interrupt: keep it tiny. IRAM_ATTR keeps it in fast internal RAM.
  static void IRAM_ATTR onEdge(void *arg) {
    auto *self = static_cast<Button *>(arg);
    self->edges_ = self->edges_ + 1;
    self->lastEdgeUs_ = uint32_t(esp_timer_get_time());  // 32 bits: read in one go, wraps safely
  }

  uint8_t pin_;
  const char *name_;
  volatile uint32_t edges_ = 0;      // written by the interrupt
  volatile uint32_t lastEdgeUs_ = 0;  // written by the interrupt
  bool pressed_ = false;
  bool longFired_ = false;
  uint8_t clicks_ = 0;
  uint32_t edgesAtRest_ = 0;
  uint32_t lastBounces_ = 0;
  uint32_t pressedAt_ = 0;
  uint32_t releasedAt_ = 0;
};

// The 1.9" ST7789 screen plus an off-screen frame buffer, set up the way every lesson since 03 uses it.
// Draw into fb() with the normal Adafruit GFX calls, then push() sends the whole picture at once.
#pragma once

#include <Adafruit_ST7789.h>
#include <SPI.h>

#include "frame_buffer.h"
#include "pins.h"

class Display {
 public:
  static constexpr int16_t kW = 320, kH = 170;  // landscape

  Display() : tft_(&SPI, PIN_TFT_CS, PIN_TFT_DC, PIN_TFT_RST), fb_(kW, kH) {}

  // Returns false if there is no memory for the frame buffer.
  bool begin(uint32_t spiHz = 40'000'000) {
    // Backlight through PWM so it can be dimmed (setBacklight). Full brightness to start.
    ledcAttach(PIN_TFT_BL, 5000, 8);
    ledcWrite(PIN_TFT_BL, 255);
    SPI.begin(PIN_TFT_SCLK, -1, PIN_TFT_MOSI, PIN_TFT_CS);
    tft_.init(170, 320);
    tft_.setSPISpeed(spiHz);
    tft_.setRotation(1);
    tft_.fillScreen(0);
    return fb_.begin();
  }

  FrameBuffer &fb() { return fb_; }
  // 0 = off, 255 = full brightness.
  void setBacklight(uint8_t level) { ledcWrite(PIN_TFT_BL, level); }
  void push() { tft_.drawRGBBitmap(0, 0, fb_.pixels(), kW, kH); }

 private:
  Adafruit_ST7789 tft_;
  FrameBuffer fb_;
};

