// Every device the radio has heard, kept by the scan callback and read by the screen.
//
// NimBLE calls onResult() in its own task for every advertisement it hears (with duplicates on,
// that's every packet, many per second per device). Each one updates one row here: the newest
// payload, a smoothed RSSI and a packet counter. The screen takes a sorted copy.
#pragma once

#include <Arduino.h>
#include <NimBLEDevice.h>

#include <algorithm>

#include "ad_format.h"
#include "ble_link.h"

namespace ble {

struct Heard {
  uint8_t addr[6] = {};  // little-endian, as on air
  uint8_t addrType = 0;
  char name[24] = "";
  int8_t rssi = -127;      // newest
  float rssiAvg = -127;    // smoothed, what the radar uses
  int8_t txPower = 127;    // 127 = not advertised
  uint16_t company = 0;    // 0 = no manufacturer data
  uint16_t appearance = 0;
  ad::Kind kind = ad::Kind::Unknown;
  bool connectable = false;
  bool scanResponse = false;   // answered an active scan
  uint8_t adv[31] = {}, advLen = 0;
  uint8_t rsp[31] = {}, rspLen = 0;
  uint32_t firstSeen = 0, lastSeen = 0, packets = 0;
  uint32_t lastInterval = 0;   // ms between the last two packets

  void addrText(char *out, size_t n) const {
    snprintf(out, n, "%02X:%02X:%02X:%02X:%02X:%02X", addr[5], addr[4], addr[3], addr[2], addr[1], addr[0]);
  }
  ad::AddrKind addrKind() const { return ad::addrKind(addrType, addr[5]); }
  const char *label() const {
    if (name[0]) return name;
    if (const char *c = ad::companyName(company)) return c;
    return ad::kindName(kind);
  }
};

class ScanTable {
 public:
  static constexpr int kMax = 48;

  // From the NimBLE task.
  void record(const NimBLEAdvertisedDevice *d) {
    const uint8_t *a = d->getAddress().getVal();
    const std::vector<uint8_t> &payload = d->getPayload();
    const uint32_t now = millis();
    portENTER_CRITICAL(&lock_);
    Heard *h = findLocked(a, d->getAddress().getType());
    if (!h) h = addLocked(a, d->getAddress().getType(), now);
    if (h) {
      h->lastInterval = h->packets ? now - h->lastSeen : 0;
      h->lastSeen = now;
      h->packets++;
      h->rssi = d->getRSSI();
      h->rssiAvg = h->rssiAvg < -126 ? h->rssi : h->rssiAvg * 0.8f + h->rssi * 0.2f;
      h->connectable = d->isConnectable();
      // NimBLE appends the scan response after the advertisement in getPayload(); getAdvLength()
      // says where the advertisement ends. A lone scan response arrives as its own report.
      const size_t advLen = std::min<size_t>(payload.size(), d->getAdvLength());
      const bool responseOnly = payload.size() <= advLen && d->getAdvType() == BLE_HCI_ADV_RPT_EVTYPE_SCAN_RSP;
      if (!responseOnly) {
        h->advLen = uint8_t(std::min<size_t>(advLen, 31));
        memcpy(h->adv, payload.data(), h->advLen);
      }
      const size_t rspFrom = responseOnly ? 0 : advLen;
      if (payload.size() > rspFrom) {
        h->scanResponse = true;
        h->rspLen = uint8_t(std::min<size_t>(payload.size() - rspFrom, 31));
        memcpy(h->rsp, payload.data() + rspFrom, h->rspLen);
      }
      if (d->haveName()) strlcpy(h->name, d->getName().c_str(), sizeof(h->name));
      if (d->haveTXPower()) h->txPower = d->getTXPower();
      if (d->haveAppearance()) h->appearance = d->getAppearance();
      if (d->haveManufacturerData()) {
        const std::string m = d->getManufacturerData();
        if (m.size() >= 2) h->company = uint16_t(uint8_t(m[0]) | (uint8_t(m[1]) << 8));
      }
      const ad::Kind k = ad::guess(h->adv, h->advLen);
      h->kind = k != ad::Kind::Unknown ? k : ad::guess(h->rsp, h->rspLen);
    }
    packets_++;
    portEXIT_CRITICAL(&lock_);
  }

  // Up to max rows, sorted by smoothed RSSI (strongest first), seen within the last maxAgeMs.
  int snapshot(Heard *out, int max, uint32_t maxAgeMs = 30000, int nearDbm = -127) {
    const uint32_t now = millis();
    int n = 0;
    portENTER_CRITICAL(&lock_);
    for (int i = 0; i < count_ && n < max; i++) {
      const Heard &h = rows_[i];
      if (now - h.lastSeen > maxAgeMs || h.rssiAvg < nearDbm) continue;
      out[n++] = h;
    }
    portEXIT_CRITICAL(&lock_);
    std::sort(out, out + n, [](const Heard &a, const Heard &b) { return a.rssiAvg > b.rssiAvg; });
    return n;
  }

  uint32_t packets() {
    portENTER_CRITICAL(&lock_);
    const uint32_t p = packets_;
    portEXIT_CRITICAL(&lock_);
    return p;
  }
  int size() {
    portENTER_CRITICAL(&lock_);
    const int n = count_;
    portEXIT_CRITICAL(&lock_);
    return n;
  }

  void clear() {
    portENTER_CRITICAL(&lock_);
    count_ = 0;
    portEXIT_CRITICAL(&lock_);
  }

 private:
  Heard *findLocked(const uint8_t *a, uint8_t type) {
    for (int i = 0; i < count_; i++)
      if (rows_[i].addrType == type && memcmp(rows_[i].addr, a, 6) == 0) return &rows_[i];
    return nullptr;
  }

  // A full table drops the device heard least recently: phones change private addresses every
  // ~15 minutes, so old rows are often the same phone under a previous name.
  Heard *addLocked(const uint8_t *a, uint8_t type, uint32_t now) {
    int slot = count_;
    if (count_ == kMax) {
      slot = 0;
      for (int i = 1; i < kMax; i++)
        if (rows_[i].lastSeen < rows_[slot].lastSeen) slot = i;
    } else {
      count_++;
    }
    rows_[slot] = Heard{};
    memcpy(rows_[slot].addr, a, 6);
    rows_[slot].addrType = type;
    rows_[slot].firstSeen = now;
    return &rows_[slot];
  }

  portMUX_TYPE lock_ = portMUX_INITIALIZER_UNLOCKED;
  Heard rows_[kMax];
  int count_ = 0;
  uint32_t packets_ = 0;
};

}  // namespace ble

// The peripheral side of a link (B3-B7): NimBLE's server callbacks, turned into ble::link() state
// and activity lines. Labs make one, hand it to the server, and override what they need.
//
// Pairing hooks are here too, because every lab after B3 meets them: a passkey to show, a number
// to compare. The passkey goes into the link state; the shell draws it over any view, and the
// button (click = yes, long press = no) or serial `yes`/`no` answers through confirm().
#pragma once

#include <Arduino.h>
#include <NimBLEDevice.h>
#include <esp_random.h>

#include "ble_link.h"

namespace ble {

inline void fillPeer(Peer &p, const NimBLEConnInfo &c) {
  strlcpy(p.addr, c.getAddress().toString().c_str(), sizeof(p.addr));
  const NimBLEAddress id = c.getIdAddress();
  if (!(id == c.getAddress())) strlcpy(p.idAddr, id.toString().c_str(), sizeof(p.idAddr));
  else p.idAddr[0] = 0;
  p.addrType = c.getAddress().getType();
  p.handle = c.getConnHandle();
  p.mtu = c.getMTU();
  p.interval = c.getConnInterval();
  p.latency = c.getConnLatency();
  p.timeout = c.getConnTimeout();
  p.encrypted = c.isEncrypted();
  p.authenticated = c.isAuthenticated();
  p.bonded = c.isBonded();
  p.keySize = c.getSecKeySize();
  p.central = c.isSlave();  // we are the slave (peripheral), so the peer is the central
}

class ServerLink : public NimBLEServerCallbacks {
 public:
  // Advertising starts again by itself after a disconnect (NimBLE's advertiseOnDisconnect).
  void onConnect(NimBLEServer *, NimBLEConnInfo &c) override {
    link().edit([&](LinkState &s) {
      s.peer = Peer{};
      fillPeer(s.peer, c);
      s.radio = Radio::Connected;
      s.advertising = false;
      s.connections++;
      s.connectedAt = millis();
      s.rxOps = s.txOps = s.rxBytes = s.txBytes = 0;
    });
    BLE_NOTE(Good, "connected: %s", c.getAddress().toString().c_str());
    BLE_NOTE(Info, "interval %.2f ms, latency %u, timeout %u ms", c.getConnInterval() * 1.25f, c.getConnLatency(), c.getConnTimeout() * 10);
  }

  void onDisconnect(NimBLEServer *server, NimBLEConnInfo &c, int reason) override {
    link().edit([&](LinkState &s) {
      s.connections = s.connections ? s.connections - 1 : 0;
      s.radio = advertiseAgain_ ? Radio::Advertising : Radio::Off;
      s.advertising = advertiseAgain_;
      s.lastDisconnect = reason;
      s.passkey = 0;
    });
    BLE_NOTE(Warn, "disconnected 0x%02X: %s", reason & 0xFF, disconnectReason(reason));
    (void)server;
  }

  void onMTUChange(uint16_t mtu, NimBLEConnInfo &c) override {
    link().edit([&](LinkState &s) { s.peer.mtu = mtu; });
    BLE_NOTE(Info, "MTU %u: %u bytes of data per packet", mtu, mtu - 3);
    (void)c;
  }

  void onConnParamsUpdate(NimBLEConnInfo &c) override {
    link().edit([&](LinkState &s) { fillPeer(s.peer, c); });
    BLE_NOTE(Info, "new params: %.2f ms, latency %u", c.getConnInterval() * 1.25f, c.getConnLatency());
  }

  void onPhyUpdate(NimBLEConnInfo &c, uint8_t tx, uint8_t rx) override {
    link().edit([&](LinkState &s) { s.peer.txPhy = tx, s.peer.rxPhy = rx; });
    BLE_NOTE(Info, "PHY now %s / %s", tx == 2 ? "2M" : tx == 3 ? "Coded" : "1M", rx == 2 ? "2M" : rx == 3 ? "Coded" : "1M");
    (void)c;
  }

  // ---- Pairing -------------------------------------------------------------------------------

  // Passkey entry, we display: six random digits, the other side types them.
  uint32_t onPassKeyDisplay() override {
    const uint32_t key = esp_random() % 1000000;
    link().edit([&](LinkState &s) { s.passkey = key ? key : 1, s.passkeyCompare = false, s.passkeySince = millis(); });
    BLE_NOTE(Warn, "passkey %06lu: type it on the other device", static_cast<unsigned long>(key));
    return key;
  }

  // Numeric comparison: both screens show the same 6 digits; a person says yes on both.
  void onConfirmPassKey(NimBLEConnInfo &c, uint32_t pin) override {
    pendingHandle_ = c.getConnHandle();
    link().edit([&](LinkState &s) { s.passkey = pin ? pin : 1, s.passkeyCompare = true, s.passkeySince = millis(); });
    BLE_NOTE(Warn, "compare %06lu: same on the phone? (click/yes)", static_cast<unsigned long>(pin));
  }

  void onAuthenticationComplete(NimBLEConnInfo &c) override {
    link().edit([&](LinkState &s) {
      fillPeer(s.peer, c);
      s.passkey = 0;
    });
    if (c.isEncrypted())
      BLE_NOTE(Good, "secured: %s%s, key %u B", c.isAuthenticated() ? "authenticated" : "Just Works", c.isBonded() ? ", bonded" : "", c.getSecKeySize());
    else
      BLE_NOTE(Bad, "pairing failed: still plain text");
  }

  void onIdentity(NimBLEConnInfo &c) override {
    link().edit([&](LinkState &s) { fillPeer(s.peer, c); });
    BLE_NOTE(Info, "identity: %s", c.getIdAddress().toString().c_str());
  }

  // Answer a numeric comparison (button or serial). False when nothing is waiting.
  bool confirm(bool yes) {
    if (pendingHandle_ == 0xFFFF) return false;
    NimBLEServer *server = NimBLEDevice::getServer();
    if (server) NimBLEDevice::injectConfirmPasskey(server->getPeerInfoByHandle(pendingHandle_), yes);
    pendingHandle_ = 0xFFFF;
    link().edit([&](LinkState &s) { s.passkey = 0; });
    BLE_NOTE(Info, "you said %s", yes ? "yes, it matches" : "no");
    return true;
  }
  bool comparing() const { return pendingHandle_ != 0xFFFF; }

  void setAdvertiseAgain(bool on) { advertiseAgain_ = on; }

 private:
  uint16_t pendingHandle_ = 0xFFFF;
  bool advertiseAgain_ = true;
};

}  // namespace ble

// Colour helpers for the 16-bit RGB565 format the ST7789 speaks: 5 bits red, 6 green, 5 blue.
#pragma once

#include <stdint.h>

constexpr uint16_t rgb(uint8_t r, uint8_t g, uint8_t b) {
  return uint16_t(((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3));
}

// Hue 0-255 around the colour wheel, saturation and value 0-255.
inline uint16_t hsv(uint8_t h, uint8_t s, uint8_t v) {
  const uint8_t region = h / 43;
  const uint8_t rem = (h - region * 43) * 6;
  const uint8_t p = (v * (255 - s)) >> 8;
  const uint8_t q = (v * (255 - ((s * rem) >> 8))) >> 8;
  const uint8_t t = (v * (255 - ((s * (255 - rem)) >> 8))) >> 8;
  switch (region) {
    case 0: return rgb(v, t, p);
    case 1: return rgb(q, v, p);
    case 2: return rgb(p, v, t);
    case 3: return rgb(p, q, v);
    case 4: return rgb(t, p, v);
    default: return rgb(v, p, q);
  }
}

// Mix two colours: k = 0 gives a, k = 255 gives b.
inline uint16_t mix(uint16_t a, uint16_t b, uint8_t k) {
  const int ar = a >> 11, ag = (a >> 5) & 63, ab = a & 31;
  const int br = b >> 11, bg = (b >> 5) & 63, bb = b & 31;
  return uint16_t(((ar + ((br - ar) * k >> 8)) << 11) | ((ag + ((bg - ag) * k >> 8)) << 5) | (ab + ((bb - ab) * k >> 8)));
}

